	descendantOccurrence.summary.valid = TRUE;
	descendantOccurrence.summary.path = oldDescendantPath;
	descendantOccurrence.summary.sourceName = "descendant.s";
	descendantOccurrence.summary.geometryKind = "wire";
	descendantOccurrence.summary.recordRole = "leaf";
	descendantOccurrence.summary.visible = TRUE;
	descendantOccurrence.summary.selectable = TRUE;
	require(descendant->setCompactOccurrenceRegistry(
	    {descendantOccurrence}) == 1,
	    "database rename descendant compact occurrence");
	(void)metadata_compiled_assembly(*descendant);
	renamedGroup->addChild(descendant);

	auto aggregateOwner = retain_node(new SoBRLDatabaseSource);
