    bool isComplete() const
    {
	SoHUDKit *hud = gizmo->getHUDKit();
	SoGroup *widget = single_hud_widget(hud);
	return !gizmo->getCamera() && hud && hud != originalHud &&
	    gizmo->getNumChildren() == 1 && gizmo->getChild(0) == hud &&
	    widget && widget->getNumChildren() >= MinimumCircleChildCount &&
	    path->getLength() == 1 &&
	    gizmo->hitTest(740, 60, 800, 600) != originalCenterPart;
    }

    TestNodeRef cameraOwner;
    TestNodeRef owner;
