using NavigationGizmoSnapshotObserver =
    NavigationGizmoPublicationObserver<NavigationGizmoSnapshotFixture>;

static void
check_navigation_gizmo_rebuild_publication()
{
    size_t positions = 0, preserved = 0, committed = 0;
    for (bool clearing : {false, true}) {
	NavigationGizmoRebuildFixture measured(clearing);
	NavigationGizmoRebuildObserver measuredObserver(measured);
	bool failed = false;
	const size_t attempts = invoke_with_failure([&] {
	    require(bool(measured.rebuild()) == !clearing,
		"navigation gizmo measured rebuild return");
	}, std::numeric_limits<size_t>::max(), failed);
	require(!failed && measured.isComplete() && measuredObserver.calls &&
	    !measuredObserver.incoherent,
	    "navigation gizmo rebuild exposed partial pointers or children");
	positions += attempts + 1;

	if (clearing) {
	    const size_t calls = measuredObserver.calls;
	    failed = false;
	    const size_t repeatedAttempts = invoke_with_failure([&] {
		require(!measured.rebuild(),
		    "repeated hidden navigation gizmo rebuild return");
	    }, 0, failed);
	    require(!failed && repeatedAttempts == 0 && measured.isComplete() &&
		measuredObserver.calls == calls,
		"repeated hidden navigation gizmo rebuild allocated, changed or notified");
	}

	for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
	    NavigationGizmoRebuildFixture fixture(clearing);
	    NavigationGizmoRebuildObserver observer(fixture);
	    failed = false;
	    invoke_with_failure([&] {
		require(bool(fixture.rebuild()) == !clearing,
		    "navigation gizmo swept rebuild return");
	    }, failAfter, failed);
	    const bool old = fixture.isOld();
	    require(old || fixture.isComplete(),
		"navigation gizmo rebuild left partial pointers or children");
	    require(!observer.incoherent,
		"navigation gizmo observer saw partial pointers or children");
	    if (old) {
		++preserved;
		require(failed && !observer.calls,
		    "failed navigation gizmo rebuild changed or notified old state");
		require(bool(fixture.rebuild()) == !clearing,
		    "navigation gizmo rebuild retry return");
	    } else {
		++committed;
	    }
	    require(fixture.isComplete(),
		"navigation gizmo rebuild retry did not complete");
	}

	NavigationGizmoRebuildFixture throwing(clearing);
	NavigationGizmoRebuildObserver observer(throwing);
	observer.throwing = true;
	failed = false;
	try {
	    (void)throwing.rebuild();
	} catch (const std::bad_alloc &) {
	    failed = true;
	}
	require(failed && throwing.isComplete() && observer.calls > 1 &&
	    !observer.incoherent && !SoDB::isNotifying(),
	    "navigation gizmo callback failure interrupted rebuild or notifications");
    }

    NavigationGizmoSnapshotFixture measuredSnapshot;
    NavigationGizmoSnapshotObserver measuredSnapshotObserver(measuredSnapshot);
    bool snapshotFailed = false;
    const size_t snapshotAttempts = invoke_with_failure([&] {
	measuredSnapshot.publish();
    }, std::numeric_limits<size_t>::max(), snapshotFailed);
    require(!snapshotFailed && measuredSnapshot.isComplete() &&
	measuredSnapshotObserver.calls && !measuredSnapshotObserver.incoherent,
	"navigation gizmo snapshot exposed partial camera or geometry state");
    positions += snapshotAttempts + 1;

    for (size_t failAfter = 0; failAfter <= snapshotAttempts; ++failAfter) {
	NavigationGizmoSnapshotFixture fixture;
	NavigationGizmoSnapshotObserver observer(fixture);
	snapshotFailed = false;
	invoke_with_failure([&] { fixture.publish(); }, failAfter,
	    snapshotFailed);
	const bool old = fixture.isOld();
	require(old || fixture.isComplete(),
	    "navigation gizmo snapshot left partial camera or geometry state");
	require(!observer.incoherent,
	    "navigation gizmo snapshot observer saw partial state");
	if (old) {
	    ++preserved;
	    require(snapshotFailed && !observer.calls,
		"failed navigation gizmo snapshot changed or notified old state");
	    fixture.publish();
	} else {
	    ++committed;
	}
	require(fixture.isComplete(),
	    "navigation gizmo snapshot retry did not complete");
    }

    NavigationGizmoSnapshotFixture throwingSnapshot;
    NavigationGizmoSnapshotObserver throwingSnapshotObserver(
	throwingSnapshot);
    throwingSnapshotObserver.throwing = true;
    snapshotFailed = false;
    try {
	throwingSnapshot.publish();
    } catch (const std::bad_alloc &) {
	snapshotFailed = true;
    }
    require(snapshotFailed && throwingSnapshot.isComplete() &&
	throwingSnapshotObserver.calls > 1 &&
	!throwingSnapshotObserver.incoherent && !SoDB::isNotifying(),
	"navigation gizmo snapshot callback failure interrupted publication");

    std::printf("PASS navigation-gizmo-rebuild-publication: %zu allocation positions, %zu preserved, %zu committed\n",
	positions, preserved, committed);
}

enum class NavigationGizmoInputOperation {
    Hover,
    Active,
    CameraAdd,
    CameraReplace,
    CameraRemove
};

struct NavigationGizmoInputFixture {
    explicit NavigationGizmoInputFixture(
	NavigationGizmoInputOperation requested) :
	operation(requested), oldCameraOwner(retain_node(new SoOrthographicCamera)),
	nextCameraOwner(retain_node(new SoOrthographicCamera)),
	finalCameraOwner(retain_node(new SoOrthographicCamera)),
	gizmoOwner(retain_node(new SoBRLNavigationGizmo)),
	oldCamera(static_cast<SoOrthographicCamera *>(oldCameraOwner.get())),
	nextCamera(static_cast<SoOrthographicCamera *>(nextCameraOwner.get())),
	finalCamera(static_cast<SoOrthographicCamera *>(finalCameraOwner.get())),
	gizmo(*static_cast<SoBRLNavigationGizmo *>(gizmoOwner.get()))
    {
	oldCamera->orientation = SbRotation(SbVec3f(0.0f, 1.0f, 0.0f),
	    oldCameraAngle);
	nextCamera->orientation = SbRotation(SbVec3f(1.0f, 0.0f, 0.0f),
	    nextCameraAngle);
	finalCamera->orientation = SbRotation(SbVec3f(0.0f, 0.0f, 1.0f),
	    finalCameraAngle);
	gizmo.style = SoBRLNavigationGizmo::CIRCLES;
	if (operation == NavigationGizmoInputOperation::CameraAdd)
	    gizmo.setCameraOrientationSnapshot(oldCamera->orientation.getValue());
	else
	    gizmo.setCamera(oldCamera);
	require(gizmo.rebuildGeometry(),
	    "navigation gizmo input initial geometry");
	originalHud = gizmo.getHUDKit();
	originalChild = gizmo.getChild(0);
	originalChildOwner = retain_node(originalChild);
	path = make_test_path(&gizmo, 0);
	old = std::make_unique<ExternalSceneSnapshot>(gizmo, false, false);
    }

    void publish()
    {
	switch (operation) {
	    case NavigationGizmoInputOperation::Hover:
		gizmo.setHoverPart(SoBRLNavigationGizmo::PART_POS_X_POS_Z);
		break;
	    case NavigationGizmoInputOperation::Active:
		gizmo.setActivePart(SoBRLNavigationGizmo::PART_NEG_X_POS_Y);
		break;
	    case NavigationGizmoInputOperation::CameraAdd:
	    case NavigationGizmoInputOperation::CameraReplace:
		gizmo.setCamera(nextCamera);
		break;
	    case NavigationGizmoInputOperation::CameraRemove:
		gizmo.setCamera(nullptr);
		break;
	}
    }

    void publishFinal()
    {
	switch (operation) {
	    case NavigationGizmoInputOperation::Hover:
		gizmo.setHoverPart(SoBRLNavigationGizmo::PART_NEG_Y_POS_Z);
		break;
	    case NavigationGizmoInputOperation::Active:
		gizmo.setActivePart(SoBRLNavigationGizmo::PART_POS_X_NEG_Z);
		break;
	    case NavigationGizmoInputOperation::CameraAdd:
	    case NavigationGizmoInputOperation::CameraReplace:
	    case NavigationGizmoInputOperation::CameraRemove:
		gizmo.setCamera(finalCamera);
		break;
	}
    }

    SoCamera *expectedCamera(bool final) const
    {
	if (operation == NavigationGizmoInputOperation::Hover ||
	    operation == NavigationGizmoInputOperation::Active)
	    return oldCamera;
	if (final)
	    return finalCamera;
	if (operation == NavigationGizmoInputOperation::CameraRemove)
	    return nullptr;
	return nextCamera;
    }

    bool isOld() const
    {
	const SoCamera *camera =
	    operation == NavigationGizmoInputOperation::CameraAdd ?
	    nullptr : oldCamera;
	return old->matches(gizmo) && gizmo.getCamera() == camera &&
	    gizmo.getHUDKit() == originalHud && gizmo.getNumChildren() == 1 &&
	    gizmo.getChild(0) == originalChild && path->getLength() == 2 &&
	    path->getTail() == originalChild;
    }

    bool isComplete(const ExternalSceneSnapshot &expected,
	bool final = false) const
    {
	return expected.matches(gizmo) &&
	    gizmo.getCamera() == expectedCamera(final) &&
	    gizmo.getHUDKit() && gizmo.getHUDKit() != originalHud &&
	    gizmo.getNumChildren() == 1 &&
	    gizmo.getChild(0) == gizmo.getHUDKit() && path->getLength() == 1;
    }

    static constexpr float oldCameraAngle = 0.25f;
    static constexpr float nextCameraAngle = 0.75f;
    static constexpr float finalCameraAngle = 1.25f;

    NavigationGizmoInputOperation operation;
    TestNodeRef oldCameraOwner;
    TestNodeRef nextCameraOwner;
    TestNodeRef finalCameraOwner;
    TestNodeRef gizmoOwner;
    SoOrthographicCamera *oldCamera;
    SoOrthographicCamera *nextCamera;
    SoOrthographicCamera *finalCamera;
    SoBRLNavigationGizmo &gizmo;
    SoHUDKit *originalHud = nullptr;
    SoNode *originalChild = nullptr;
    TestNodeRef originalChildOwner = retain_node(nullptr);
    TestPathRef path;
    std::unique_ptr<ExternalSceneSnapshot> old;
};

struct NavigationGizmoInputObserver {
    NavigationGizmoInputObserver(NavigationGizmoInputFixture &target,
	const ExternalSceneSnapshot &next) : fixture(target), expected(next),
	node(observe, this), path(observe, this)
    {
	node.setPriority(0);
	node.attach(&fixture.gizmo);
	path.setPriority(0);
	path.attach(fixture.path.get());
	SoField *observedField = nullptr;
	if (fixture.operation == NavigationGizmoInputOperation::Hover)
	    observedField = &fixture.gizmo.hoverPart;
	else if (fixture.operation == NavigationGizmoInputOperation::Active)
	    observedField = &fixture.gizmo.activePart;
	if (observedField) {
	    this->field = std::make_unique<SoFieldSensor>(observe, this);
	    this->field->setPriority(0);
	    this->field->attach(observedField);
	}
    }

    static void observe(void *data, SoSensor *)
    {
	auto &self = *static_cast<NavigationGizmoInputObserver *>(data);
	++self.calls;
	self.incoherent = self.incoherent ||
	    !self.fixture.isComplete(self.expected);
	if (self.throwing)
	    throw std::bad_alloc();
    }

    NavigationGizmoInputFixture &fixture;
    const ExternalSceneSnapshot &expected;
    SoNodeSensor node;
    SoPathSensor path;
    std::unique_ptr<SoFieldSensor> field;
    size_t calls = 0;
    bool incoherent = false;
    bool throwing = false;
};

struct NavigationGizmoInputReentry {
    NavigationGizmoInputReentry(NavigationGizmoInputFixture &target,
	const ExternalSceneSnapshot &next) : fixture(target), expected(next) {}

    static void observe(void *data, SoSensor *)
    {
	auto &self = *static_cast<NavigationGizmoInputReentry *>(data);
	++self.calls;
	if (!self.triggered) {
	    self.triggered = true;
	    self.fixture.publishFinal();
	}
	self.incoherent = self.incoherent ||
	    !self.fixture.isComplete(self.expected, true);
    }

    NavigationGizmoInputFixture &fixture;
    const ExternalSceneSnapshot &expected;
    size_t calls = 0;
    bool triggered = false;
    bool incoherent = false;
};

struct NavigationGizmoUnrealizedCameraFixture {
    explicit NavigationGizmoUnrealizedCameraFixture(
	NavigationGizmoInputOperation requested) : operation(requested),
	oldCameraOwner(retain_node(new SoOrthographicCamera)),
	nextCameraOwner(retain_node(new SoOrthographicCamera)),
	gizmoOwner(retain_node(new SoBRLNavigationGizmo)),
	oldCamera(static_cast<SoOrthographicCamera *>(oldCameraOwner.get())),
	nextCamera(static_cast<SoOrthographicCamera *>(nextCameraOwner.get())),
	gizmo(*static_cast<SoBRLNavigationGizmo *>(gizmoOwner.get()))
    {
	if (operation != NavigationGizmoInputOperation::CameraAdd)
	    gizmo.setCamera(oldCamera);
    }

    void publish()
    {
	gizmo.setCamera(operation == NavigationGizmoInputOperation::CameraRemove ?
	    nullptr : nextCamera);
    }

    bool isOld() const
    {
	return !gizmo.getNumChildren() && !gizmo.getHUDKit() &&
	    gizmo.getCamera() ==
		(operation == NavigationGizmoInputOperation::CameraAdd ?
		 nullptr : oldCamera);
    }

    bool isComplete() const
    {
	return !gizmo.getNumChildren() && !gizmo.getHUDKit() &&
	    gizmo.getCamera() ==
		(operation == NavigationGizmoInputOperation::CameraRemove ?
		 nullptr : nextCamera);
    }

    NavigationGizmoInputOperation operation;
    TestNodeRef oldCameraOwner;
    TestNodeRef nextCameraOwner;
    TestNodeRef gizmoOwner;
    SoOrthographicCamera *oldCamera;
    SoOrthographicCamera *nextCamera;
    SoBRLNavigationGizmo &gizmo;
};

static void
check_navigation_gizmo_input_publication()
{
    const std::array<NavigationGizmoInputOperation, 5> operations{{
	NavigationGizmoInputOperation::Hover,
	NavigationGizmoInputOperation::Active,
	NavigationGizmoInputOperation::CameraAdd,
	NavigationGizmoInputOperation::CameraReplace,
	NavigationGizmoInputOperation::CameraRemove
    }};
    for (const auto operation : operations) {
	NavigationGizmoInputFixture warmup(operation);
	warmup.publish();
    }

    size_t positions = 0, preserved = 0, committed = 0;
    for (const auto operation : operations) {
	NavigationGizmoInputFixture reference(operation);
	reference.publish();
	ExternalSceneSnapshot expected(reference.gizmo, false, false);
	require(reference.isComplete(expected),
	    "navigation gizmo input reference state");

	NavigationGizmoInputFixture measured(operation);
	NavigationGizmoInputObserver measuredObserver(measured, expected);
	bool failed = false;
	const size_t attempts = invoke_with_failure([&] { measured.publish(); },
	    std::numeric_limits<size_t>::max(), failed);
	require(!failed && measured.isComplete(expected) &&
	    measuredObserver.calls && !measuredObserver.incoherent,
	    "navigation gizmo input did not publish one complete state");
	positions += attempts + 1;

	const size_t calls = measuredObserver.calls;
	failed = false;
	const size_t noOpAttempts = invoke_with_failure(
	    [&] { measured.publish(); }, 0, failed);
	require(!failed && noOpAttempts == 0 &&
	    measured.isComplete(expected) && measuredObserver.calls == calls,
	    "navigation gizmo input no-op allocated, changed or notified");

	for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
	    NavigationGizmoInputFixture fixture(operation);
	    NavigationGizmoInputObserver observer(fixture, expected);
	    failed = false;
	    invoke_with_failure([&] { fixture.publish(); }, failAfter, failed);
	    const bool old = fixture.isOld();
	    require(old || fixture.isComplete(expected),
		"navigation gizmo input retained a partial state");
	    require(!observer.incoherent,
		"navigation gizmo input observer saw a partial state");
	    if (old) {
		++preserved;
		require(failed && !observer.calls,
		    "failed navigation gizmo input changed old state");
		fixture.publish();
	    } else {
		++committed;
	    }
	    require(fixture.isComplete(expected),
		"navigation gizmo input retry did not complete");
	}

	NavigationGizmoInputFixture throwing(operation);
	NavigationGizmoInputObserver observer(throwing, expected);
	observer.throwing = true;
	failed = false;
	try { throwing.publish(); }
	catch (const std::bad_alloc &) { failed = true; }
	require(failed && throwing.isComplete(expected) && observer.calls > 1 &&
	    !observer.incoherent && !SoDB::isNotifying(),
	    "navigation gizmo input callback failure changed publication");

	NavigationGizmoInputFixture finalReference(operation);
	finalReference.publishFinal();
	ExternalSceneSnapshot finalExpected(finalReference.gizmo, false, false);
	require(finalReference.isComplete(finalExpected, true),
	    "navigation gizmo input reentry reference state");
	NavigationGizmoInputFixture reentrant(operation);
	NavigationGizmoInputReentry reentry(reentrant, finalExpected);
	SoNodeSensor sensor(NavigationGizmoInputReentry::observe, &reentry);
	sensor.setPriority(0);
	sensor.attach(&reentrant.gizmo);
	reentrant.publish();
	sensor.detach();
	require(reentry.triggered && reentry.calls > 1 && !reentry.incoherent &&
	    reentrant.isComplete(finalExpected, true),
	    "navigation gizmo input reentry did not retain later successor");
    }

    for (const auto operation : {
	NavigationGizmoInputOperation::CameraAdd,
	NavigationGizmoInputOperation::CameraReplace,
	NavigationGizmoInputOperation::CameraRemove}) {
	NavigationGizmoUnrealizedCameraFixture measured(operation);
	SoNodeSensor measuredSensor;
	measuredSensor.attach(&measured.gizmo);
	bool failed = false;
	const size_t attempts = invoke_with_failure([&] { measured.publish(); },
	    std::numeric_limits<size_t>::max(), failed);
	require(!failed && measured.isComplete() &&
	    measuredSensor.getTriggerNode() == nullptr,
	    "unrealized navigation camera publication changed the graph");
	positions += attempts + 1;

	failed = false;
	const size_t noOpAttempts = invoke_with_failure(
	    [&] { measured.publish(); }, 0, failed);
	require(!failed && noOpAttempts == 0 && measured.isComplete(),
	    "unrealized navigation camera no-op allocated or changed");

	for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
	    NavigationGizmoUnrealizedCameraFixture fixture(operation);
	    failed = false;
	    invoke_with_failure([&] { fixture.publish(); }, failAfter, failed);
	    const bool old = fixture.isOld();
	    require(old || fixture.isComplete(),
		"unrealized navigation camera retained partial ownership");
	    if (old) {
		++preserved;
		require(failed,
		    "unrealized navigation camera rejected without failure");
		fixture.publish();
	    } else {
		++committed;
	    }
	    require(fixture.isComplete(),
		"unrealized navigation camera retry did not complete");
	}
    }

    NavigationGizmoUnrealizedCameraFixture snapshot(
	NavigationGizmoInputOperation::CameraReplace);
    SoNodeSensor snapshotSensor;
    snapshotSensor.attach(&snapshot.gizmo);
    bool snapshotFailed = false;
    const size_t snapshotAttempts = invoke_with_failure([&] {
	snapshot.gizmo.setCameraOrientationSnapshot(SbRotation::identity());
    }, 0, snapshotFailed);
    require(!snapshotFailed && snapshotAttempts == 0 &&
	!snapshot.gizmo.getCamera() && !snapshot.gizmo.getNumChildren() &&
	!snapshot.gizmo.getHUDKit() && snapshotSensor.getTriggerNode() == nullptr,
	"unrealized fixed navigation snapshot allocated or changed the graph");

    std::printf("PASS navigation-gizmo-input-publication: %zu hover/active/camera allocation positions, %zu preserved, %zu committed\n",
	positions, preserved, committed);
}

struct CuttingAffordanceRebuildFixture {
    explicit CuttingAffordanceRebuildFixture(bool clear) :
	clearing(clear),
	cameraOwner(retain_node(new SoOrthographicCamera))
    {
	controller.setViewportSize(320, 240);
	controller.setCamera(static_cast<SoCamera *>(cameraOwner.get()));
	const SbPlane initial(SbVec3f(0.0f, 0.0f, 1.0f),
	    SbVec3f(0.0f, 0.0f, 0.0f));
	require(controller.setCuttingPlane(initial),
	    "cutting affordance initial plane");
	controller.setCuttingPlaneEnabled(TRUE);
	presentation = controller.getFramebufferOverlayRoot();
	affordance = findAffordance();
	require(affordance && affordance->getNumChildren() == 1,
	    "cutting affordance initial rebuild");
	originalHud = affordance->getChild(0);
	originalHudOwner = retain_node(originalHud);
	path = make_test_path(affordance, 0);
    }
    SoSeparator *findAffordance() const
    {
	if (!presentation)
	    return nullptr;
	for (int i = 0; i < presentation->getNumChildren(); ++i) {
	    SoNode *child = presentation->getChild(i);
	    if (child && child->isOfType(SoSeparator::getClassTypeId()) &&
		bu_strcmp(child->getName().getString(),
		    "BObolCuttingPlaneAffordance") == 0)
		return static_cast<SoSeparator *>(child);
	}
	return nullptr;
    }
    void rebuild()
    {
	if (clearing) {
	    controller.setCuttingPlaneEnabled(FALSE);
	    return;
	}
	const SbPlane next(SbVec3f(0.0f, 1.0f, 0.0f),
	    SbVec3f(0.0f, 2.0f, 0.0f));
	require(controller.setCuttingPlane(next),
	    "cutting affordance replacement plane");
    }
    void retry()
    {
	rebuild();
    }
    bool isOld() const
    {
	return findAffordance() == affordance &&
	    affordance->getNumChildren() == 1 &&
	    affordance->getChild(0) == originalHud && path->getLength() == 2 &&
	    path->getTail() == originalHud && path->getIndex(1) == 0;
    }
    bool isComplete() const
    {
	if (findAffordance() != affordance || path->getLength() != 1)
	    return false;
	if (clearing)
	    return affordance->getNumChildren() == 0;
	if (affordance->getNumChildren() != 1 ||
	    affordance->getChild(0) == originalHud ||
	    !affordance->getChild(0)->isOfType(SoHUDKit::getClassTypeId()))
	    return false;
	SoGroup *widget = single_hud_widget(
	    static_cast<SoHUDKit *>(affordance->getChild(0)));
	if (!widget || widget->getNumChildren() != 6 ||
	    !widget->getChild(0)->isOfType(SoDepthBuffer::getClassTypeId()) ||
	    !widget->getChild(1)->isOfType(SoLightModel::getClassTypeId()) ||
	    !widget->getChild(2)->isOfType(SoMaterial::getClassTypeId()) ||
	    !widget->getChild(3)->isOfType(SoDrawStyle::getClassTypeId()) ||
	    !widget->getChild(4)->isOfType(SoCoordinate3::getClassTypeId()) ||
	    !widget->getChild(5)->isOfType(SoLineSet::getClassTypeId()))
	    return false;
	const auto *coordinates =
	    static_cast<const SoCoordinate3 *>(widget->getChild(4));
	const auto *lines = static_cast<const SoLineSet *>(widget->getChild(5));
	return coordinates->point.getNum() == 36 &&
	    lines->numVertices.getNum() == 18;
    }

    bool clearing;
    TestNodeRef cameraOwner;
    BObolViewController controller;
    SoGroup *presentation = nullptr;
    SoSeparator *affordance = nullptr;
    SoNode *originalHud = nullptr;
    TestNodeRef originalHudOwner = retain_node(nullptr);
    TestPathRef path;
};

