static BObolSceneLightRealization
test_scene_light(int kind, const SbVec3f &position,
	const SbVec3f &direction, float intensity, const char *name)
{
    BObolSceneLightRealization light;
    light.kind = kind;
    light.position = position;
    light.direction = direction;
    light.color = SbColor(0.25f, 0.50f, 0.75f);
    light.intensity = intensity;
    light.coneAngleDeg = 120.0f;
    light.name = name;
    return light;
}

static bool test_scene_light_group_matches(SoGroup *group,
    const std::vector<BObolSceneLightRealization> &expected, SbBool enabled);

struct SceneLightsRebuildFixture {
    explicit SceneLightsRebuildFixture(bool clear) : clearing(clear)
    {
	controller.setSceneLightsEnabled(TRUE);
	std::vector<BObolSceneLightRealization> initial;
	initial.push_back(test_scene_light(BOBOL_SCENE_LIGHT_POINT,
	    SbVec3f(1.0f, 2.0f, 3.0f), SbVec3f(), 0.20f, "old-point"));
	controller.setSceneLights(initial);
	group = static_cast<SoGroup *>(controller.getSceneLightsRoot());
	require(group && group->getNumChildren() == 1,
	    "scene lights initial rebuild");
	original.push_back(group->getChild(0));
	originalOwners.push_back(retain_node(group->getChild(0)));
	paths.push_back(make_test_path(group, 0));

	if (!clearing) {
	    next.push_back(test_scene_light(BOBOL_SCENE_LIGHT_DIRECTIONAL,
		SbVec3f(), SbVec3f(1.0f, 0.0f, 0.0f), 0.35f,
		"new-directional"));
	    next.push_back(test_scene_light(BOBOL_SCENE_LIGHT_SPOT,
		SbVec3f(4.0f, 5.0f, 6.0f), SbVec3f(0.0f, -1.0f, 0.0f),
		0.55f, "new-spot"));
	    next.push_back(test_scene_light(BOBOL_SCENE_LIGHT_POINT,
		SbVec3f(7.0f, 8.0f, 9.0f), SbVec3f(), 0.75f,
		"new-point"));
	}
    }
    void rebuild()
    {
	controller.setSceneLights(next);
    }
    bool pathsOld() const
    {
	for (size_t i = 0; i < paths.size(); ++i)
	    if (paths[i]->getLength() != 2 ||
		paths[i]->getTail() != original[i] ||
		paths[i]->getIndex(1) != static_cast<int>(i))
		return false;
	return true;
    }
    bool isOld() const
    {
	return controller.getSceneLightsRoot() == group && pathsOld() &&
	    group->getNumChildren() == static_cast<int>(original.size()) &&
	    group->getChild(0) == original[0];
    }
    bool isComplete() const
    {
	if (controller.getSceneLightsRoot() != group)
	    return false;
	for (const auto &path : paths)
	    if (path->getLength() != 1)
		return false;
	return test_scene_light_group_matches(group, next, TRUE);
    }

    bool clearing;
    BObolViewController controller;
    SoGroup *group = nullptr;
    std::vector<BObolSceneLightRealization> next;
    std::vector<SoNode *> original;
    std::vector<TestNodeRef> originalOwners;
    std::vector<TestPathRef> paths;
};

