static void
check_feature_custom_overlay_publication()
{
    FeatureCustomOverlayPublicationFixture measured;
    FeatureCustomOverlayPublicationObserver measuredObserver(measured);
    bool failed = false;
    const size_t attempts = invoke_with_failure([&] {
	require(measured.publish().isValid(),
	    "custom overlay publication measurement");
    }, std::numeric_limits<size_t>::max(), failed);
    require(!failed && measured.completeWithResult() &&
	measuredObserver.graphCalls == 1 && measuredObserver.frameCalls == 1 &&
	!measuredObserver.incoherent,
	"custom node overlay publication was not observed exactly once and complete");

    size_t preserved = 0;
    size_t committed = 0;
    for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
	FeatureCustomOverlayPublicationFixture fixture;
	FeatureCustomOverlayPublicationObserver observer(fixture);
	failed = false;
	invoke_with_failure([&] { fixture.publish(); }, failAfter, failed);
	const bool old = fixture.original();
	const bool complete = fixture.completeWithResult();
	if (!old && !complete)
	    std::fprintf(stderr,
		"custom overlay failure position=%zu failed=%d graph=%zu frame=%zu result=%zu complete=%d\n",
		failAfter, failed ? 1 : 0, observer.graphCalls,
		observer.frameCalls, fixture.resultCalls,
		fixture.complete() ? 1 : 0);
	require(old || complete,
	    "custom overlay allocation failure left a partial publication");
	require(!observer.incoherent,
	    "custom overlay observer saw a partial publication");
	if (old) {
	    ++preserved;
	    require(failed && !observer.graphCalls && !observer.frameCalls,
		"failed custom overlay publication notified its predecessor");
	    fixture.retry();
	} else {
	    ++committed;
	}
	require(fixture.completeWithResult(),
	    "custom overlay publication did not reach complete state");
    }
    require(preserved && committed,
	"custom overlay sweep did not exercise both publication outcomes");
    std::printf("PASS feature-custom-overlay-publication: %zu allocation positions, %zu preserved, %zu committed; one complete graph/frame/result publication\n",
	attempts + 1, preserved, committed);
}

