static void
check_window_first_open_publication()
{
    size_t positions = 0;
    size_t preserved = 0;
    size_t committed = 0;
    for (bool automatic : {false, true}) {
	WindowFirstOpenPublicationFixture measured(automatic);
	bool failed = false;
	const size_t attempts = invoke_with_failure(
	    [&] { measured.open(); }, std::numeric_limits<size_t>::max(),
	    failed);
	require(!failed && measured.isComplete() && measured.calls == 1 &&
	    !measured.incoherent,
	    "first window open did not publish one complete host policy");

	const size_t calls = measured.calls;
	const size_t noOpAttempts = invoke_with_failure(
	    [&] { measured.open(); }, 0, failed);
	require(!failed && noOpAttempts == 0 && measured.isComplete() &&
	    measured.calls == calls,
	    "unchanged first-open policy allocated, changed or notified");

	for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
	    WindowFirstOpenPublicationFixture fixture(automatic);
	    failed = false;
	    invoke_with_failure([&] { fixture.open(); }, failAfter, failed);
	    const bool old = fixture.isOld();
	    require(old || fixture.isComplete(),
		"first window open retained a partial host policy");
	    require(!fixture.incoherent,
		"first window open callback observed a partial host policy");
	    if (old) {
		++preserved;
		require(failed && !fixture.calls,
		    "failed first window open changed state or notified");
		fixture.open();
	    } else {
		++committed;
	    }
	    require(fixture.isComplete(),
		"first window open retry did not complete");
	}
	positions += attempts + 1;

	WindowFirstOpenPublicationFixture throwing(automatic);
	throwing.throwing = true;
	failed = false;
	try {
	    throwing.open();
	} catch (const std::bad_alloc &) {
	    failed = true;
	}
	require(failed && throwing.isComplete() && throwing.calls == 1 &&
	    !throwing.incoherent && !SoDB::isNotifying(),
	    "first window open callback failure interrupted host policy");
    }

    auto validConstructedHost = [](const BObolWindowHost &host) {
	const BObolViewController *controller = host.getController();
	if (!controller || host.isOpen())
	    return false;
	SoNode *root = controller->getSceneRoot();
	const SbViewportRegion &region = controller->getViewportRegion();
	return root && root->isOfType(SoGroup::getClassTypeId()) &&
	    controller->getViewport()->getViewportRegion() == region &&
	    controller->getRenderManager()->getViewportRegion() == region &&
	    controller->getHostWorkSnapshot().flags == BOBOL_HOST_WORK_NONE;
    };

    std::unique_ptr<BObolWindowHost> measuredHost;
    bool failed = false;
    const size_t constructionAttempts = invoke_with_failure(
	[&] { measuredHost = std::make_unique<BObolWindowHost>(); },
	std::numeric_limits<size_t>::max(), failed);
    require(!failed && measuredHost && validConstructedHost(*measuredHost),
	"neutral host construction did not establish a quiet root invariant");

    size_t constructionPreserved = 0;
    size_t constructionCommitted = 0;
    for (size_t failAfter = 0; failAfter <= constructionAttempts; ++failAfter) {
	std::unique_ptr<BObolWindowHost> host;
	failed = false;
	invoke_with_failure(
	    [&] { host = std::make_unique<BObolWindowHost>(); },
	    failAfter, failed);
	if (host) {
	    ++constructionCommitted;
	    require(!failed && validConstructedHost(*host),
		"neutral host construction exposed an incomplete root invariant");
	} else {
	    ++constructionPreserved;
	    require(failed,
		"neutral host construction failed without reporting allocation denial");
	}
    }

    std::printf("PASS window-first-open-publication: %zu ordinary/automatic open allocation positions, %zu preserved, %zu committed; %zu construction positions, %zu rejected, %zu complete\n",
	positions, preserved, committed, constructionAttempts + 1,
	constructionPreserved, constructionCommitted);
}

