static bool
scene_contains_node(SoNode *root, SoNode *node)
{
    if (!root || !node)
	return false;
    SoSearchAction search;
    search.setNode(node);
    search.setInterest(SoSearchAction::FIRST);
    search.apply(root);
    return search.getPath() != NULL;
}

static bool
default_camera_is_private(const BObolViewController &controller)
{
    SoCamera *camera = controller.getCamera();
    const SoViewport *viewport = controller.getViewport();
    const SoRenderManager *manager = controller.getRenderManager();
    return camera &&
	camera->isOfType(SoOrthographicCamera::getClassTypeId()) &&
	viewport && viewport->getCamera() == camera &&
	viewport->getRoot()->findChild(camera) >= 0 &&
	manager && manager->getCamera() == camera &&
	!scene_contains_node(controller.getSceneRoot(), camera);
}

static bool
valid_default_controller(const BObolViewController &controller)
{
    SoNode *root = controller.getSceneRoot();
    const SbViewportRegion &region = controller.getViewportRegion();
    return root && root->isOfType(SoBRLSceneGroup::getClassTypeId()) &&
	default_camera_is_private(controller) &&
	controller.getViewport()->getViewportRegion() == region &&
	controller.getRenderManager()->getViewportRegion() == region &&
	controller.getHostWorkSnapshot().flags == BOBOL_HOST_WORK_NONE;
}

static void
check_window_controller_attachment()
{
    std::unique_ptr<BObolViewController> measuredController;
    bool failed = false;
    const size_t constructionAttempts = invoke_with_failure(
	[&] { measuredController = std::make_unique<BObolViewController>(); },
	std::numeric_limits<size_t>::max(), failed);
    require(!failed && measuredController &&
	valid_default_controller(*measuredController),
	"default controller construction did not establish a hostable invariant");

    size_t constructionRejected = 0;
    size_t constructionComplete = 0;
    for (size_t failAfter = 0; failAfter <= constructionAttempts; ++failAfter) {
	std::unique_ptr<BObolViewController> controller;
	failed = false;
	invoke_with_failure(
	    [&] { controller = std::make_unique<BObolViewController>(); },
	    failAfter, failed);
	if (controller) {
	    ++constructionComplete;
	    require(!failed && valid_default_controller(*controller),
		"default controller construction exposed incomplete state");
	} else {
	    ++constructionRejected;
	    require(failed,
		"default controller construction failed without allocation denial");
	}
    }

    BObolLodService teardownService;
    auto teardownController = std::make_unique<BObolViewController>();
    teardownController->setLodService(&teardownService);
    teardownController->setLodControlTransitionTracing(TRUE, 4);
    failed = false;
    const size_t teardownAllocations = invoke_with_failure(
	[&] { teardownController.reset(); }, 0, failed);
    require(!failed && !teardownController && teardownAllocations == 0,
	"controller teardown used a live allocation or left its service attached");

    auto validEndpoint = [](const bobol_display_endpoint_t *endpoint) {
	const auto *controller = endpoint ?
	    static_cast<const BObolViewController *>(
		bobol_display_endpoint_controller(endpoint)) : NULL;
	return controller && valid_default_controller(*controller);
    };
    bobol_display_endpoint_t *warmEndpoint = bobol_display_endpoint_create(
	NULL, BOBOL_ENDPOINT_OWN_CONTROLLER);
    require(validEndpoint(warmEndpoint),
	"default endpoint warmup did not establish a complete controller");
    bobol_display_endpoint_destroy(warmEndpoint);

    bobol_display_endpoint_t *measuredEndpoint = NULL;
    failed = false;
    const size_t endpointAttempts = invoke_with_failure(
	[&] {
	    measuredEndpoint = bobol_display_endpoint_create(
		NULL, BOBOL_ENDPOINT_OWN_CONTROLLER);
	}, std::numeric_limits<size_t>::max(), failed);
    require(!failed && validEndpoint(measuredEndpoint),
	"default endpoint did not contain constructor failure");
    bobol_display_endpoint_destroy(measuredEndpoint);

    size_t endpointRejected = 0;
    size_t endpointComplete = 1;
    for (size_t failAfter = 0; failAfter < endpointAttempts; ++failAfter) {
	bobol_display_endpoint_t *endpoint = NULL;
	failed = false;
	invoke_with_failure(
	    [&] {
		endpoint = bobol_display_endpoint_create(
		    NULL, BOBOL_ENDPOINT_OWN_CONTROLLER);
	    }, failAfter, failed);
	require(!failed,
	    "default endpoint allowed a constructor exception across its C API");
	if (endpoint) {
	    ++endpointComplete;
	    require(validEndpoint(endpoint),
		"default endpoint exposed an incomplete controller");
	    bobol_display_endpoint_destroy(endpoint);
	} else {
	    ++endpointRejected;
	}
    }

    size_t attachmentAllocations = 0;
    size_t openPositions = 0;
    for (bool automatic : {false, true}) {
	WindowControllerAttachmentFixture measured(automatic);
	failed = false;
	const size_t attachAttempts = invoke_with_failure(
	    [&] { measured.attach(); }, 0, failed);
	require(!failed && attachAttempts == 0 && measured.isAttached() &&
	    measured.calls == 0 && !measured.incoherent,
	    "borrowed controller attachment allocated, notified or changed policy");
	attachmentAllocations += attachAttempts;

	failed = false;
	const size_t attempts = invoke_with_failure(
	    [&] { measured.open(); }, std::numeric_limits<size_t>::max(),
	    failed);
	require(!failed && measured.isComplete() && measured.calls == 1 &&
	    !measured.incoherent,
	    "borrowed controller open did not publish one complete host policy");
	openPositions += attempts + 1;

	const size_t calls = measured.calls;
	failed = false;
	const size_t noOpAttempts = invoke_with_failure(
	    [&] { measured.attach(); }, 0, failed);
	require(!failed && noOpAttempts == 0 && measured.isComplete() &&
	    measured.calls == calls,
	    "same-controller attachment closed, allocated or notified");

	WindowControllerAttachmentFixture throwing(automatic);
	throwing.attach();
	throwing.throwing = true;
	failed = false;
	try {
	    throwing.open();
	} catch (const std::bad_alloc &) {
	    failed = true;
	}
	require(failed && throwing.isComplete() && throwing.calls == 1 &&
	    !throwing.incoherent && !SoDB::isNotifying(),
	    "borrowed controller callback failure interrupted host policy");
    }

    for (bool nullRoot : {true, false}) {
	BObolViewController invalid;
	TestNodeRef nongroup = retain_node(new SoCube);
	invalid.setSceneRoot(nullRoot ? NULL : nongroup.get());
	invalid.clearRenderRequest();
	invalid.clearProgressiveWorkPending();
	BObolWindowHost host;
	BObolViewController *precedingController = host.getController();
	const BObolWindowDesc preceding = host.getDesc();
	const uint64_t invalidWorkRevision =
	    invalid.getHostWorkSnapshot().revision;
	failed = false;
	bobol_display_endpoint_t *invalidEndpoint = NULL;
	const size_t endpointValidationAttempts = invoke_with_failure(
	    [&] {
		invalidEndpoint = bobol_display_endpoint_create(&invalid, 0);
	    }, 0, failed);
	require(!failed && endpointValidationAttempts == 0 && !invalidEndpoint &&
	    invalid.getHostWorkSnapshot().revision == invalidWorkRevision,
	    "invalid endpoint controller was allocated, accepted or changed");
	failed = false;
	const size_t attempts = invoke_with_failure(
	    [&] {
		require(!host.attachController(&invalid, FALSE),
		    "invalid borrowed controller rejection");
	    }, 0, failed);
	require(!failed && attempts == 0 &&
	    host.getController() == precedingController && !host.isOpen() &&
	    window_desc_matches(host.getDesc(), preceding) &&
	    invalid.getHostWorkSnapshot().revision == invalidWorkRevision,
	    "invalid attachment changed the host or borrowed controller");
    }

    std::printf("PASS window-controller-attachment: %zu controller construction positions, %zu rejected, %zu complete; %zu endpoint positions, %zu rejected, %zu complete; %zu attachment allocations; %zu teardown allocations; %zu ordinary/automatic first-open positions\n",
	constructionAttempts + 1, constructionRejected, constructionComplete,
	endpointAttempts + 1, endpointRejected, endpointComplete,
	attachmentAllocations, teardownAllocations, openPositions);
}

static void
check_headless_camera_invariant()
{
    BObolHeadlessWindowHost host;
    BObolViewController *controller = host.getController();
    require(controller && valid_default_controller(*controller),
	"default headless controller lacks a private active camera");
    SoCamera *camera = controller->getCamera();
    SoNode *sceneRoot = controller->getSceneRoot();
    const int sceneChildren = static_cast<SoGroup *>(sceneRoot)->getNumChildren();

    BObolWindowDesc desc;
    desc.mode = BOBOL_WINDOW_TOPLEVEL;
    desc.backend = BOBOL_WINDOW_BACKEND_QT;
    desc.width = 11;
    desc.height = 7;
    desc.title = "headless-camera-invariant";
    desc.display = "headless-camera-display";
    desc.nativeIdHint = "headless-camera-native";
    desc.visible = TRUE;
    require(host.open(&desc) == 0 && host.isOpen(),
	"default headless controller did not open");
    require(controller->getCamera() == camera &&
	default_camera_is_private(*controller) &&
	controller->getSceneRoot() == sceneRoot &&
	static_cast<SoGroup *>(sceneRoot)->getNumChildren() == sceneChildren,
	"headless open replaced its camera or changed modeled scene content");

    for (bool misplacedCamera : {false, true}) {
	TestNodeRef borrowedRoot = retain_node(new SoGroup);
	TestNodeRef sceneCamera = retain_node(misplacedCamera ?
	    static_cast<SoNode *>(new SoOrthographicCamera) : NULL);
	if (sceneCamera)
	    static_cast<SoGroup *>(borrowedRoot.get())->addChild(sceneCamera.get());
	BObolViewController borrowed(borrowedRoot.get(), NULL);
	borrowed.clearRenderRequest();
	borrowed.clearProgressiveWorkPending();
	BObolHeadlessWindowHost borrowedHost;
	require(borrowedHost.attachController(&borrowed, FALSE),
	    "camera-less borrowed controller attachment");
	const BObolWindowDesc preceding = borrowedHost.getDesc();
	const int precedingChildren =
	    static_cast<SoGroup *>(borrowedRoot.get())->getNumChildren();
	const uint64_t workRevision = borrowed.getHostWorkSnapshot().revision;
	bool failed = false;
	int opened = 0;
	const size_t attempts = invoke_with_failure(
	    [&] { opened = borrowedHost.open(&desc); }, 0, failed);
	require(!failed && attempts == 0 && opened != 0 &&
	    !borrowedHost.isOpen() &&
	    window_desc_matches(borrowedHost.getDesc(), preceding) &&
	    borrowed.getCamera() == NULL &&
	    borrowed.getRenderContextManager() == NULL &&
	    borrowed.getHostWorkSnapshot().revision == workRevision &&
	    static_cast<SoGroup *>(borrowedRoot.get())->getNumChildren() ==
		precedingChildren &&
	    (!sceneCamera || scene_contains_node(borrowedRoot.get(),
		sceneCamera.get())),
	    "headless open adopted scene camera or changed rejected controller");
    }

    std::puts("PASS headless-camera-invariant: default camera remains private across open; camera-less and scene-camera controllers reject without allocation or mutation");
}

struct HeadlessOpenContextPublicationFixture {
    static constexpr unsigned int Width = 13;
    static constexpr unsigned int Height = 9;

    explicit HeadlessOpenContextPublicationFixture(bool automaticLod) :
	automatic(automaticLod)
    {
	BObolViewController *controller = host.getController();
	require(controller != nullptr, "headless context host controller");
	require(host.getContextManager() != nullptr &&
	    controller->getRenderContextManager() == nullptr,
	    "headless context initial provider policy");
	preceding = host.getDesc();
	committed.mode = BOBOL_WINDOW_HEADLESS;
	committed.backend = BOBOL_WINDOW_BACKEND_OFFSCREEN;
	committed.width = Width;
	committed.height = Height;
	committed.title = "ctx";
	committed.display = "";
	committed.nativeIdHint = "";
	committed.visible = FALSE;

	if (automatic) {
	    struct bv_lod_policy policy;
	    bv_lod_policy_init(&policy);
	    policy.policy = BV_LOD_AUTO;
	    policy.mesh_enabled = policy.csg_enabled = 1;
	    controller->setViewLodPolicy(&policy);
	    controller->setLodAutoSubmit(TRUE);
	}
	controller->clearRenderRequest();
	controller->clearProgressiveWorkPending();
	initialRegion = controller->getViewportRegion();
	nextRegion = initialRegion;
	nextRegion.setWindowSize(static_cast<short>(Width),
	    static_cast<short>(Height));
	nextRegion.setViewportPixels(0, 0, static_cast<short>(Width),
	    static_cast<short>(Height));
	initialViewRevision = controller->getLodViewRevision();
	controller->setFrameRequestCallback(wake, this);
	armed = true;
	require(isOld(), "headless context initial host state");
    }

    ~HeadlessOpenContextPublicationFixture()
    {
	host.getController()->clearFrameRequestCallback(this);
    }

    bool regionsMatch(const SbViewportRegion &expected) const
    {
	const BObolViewController *controller = host.getController();
	return controller->getViewportRegion() == expected &&
	    controller->getViewport()->getViewportRegion() == expected &&
	    controller->getRenderManager()->getViewportRegion() == expected;
    }

    bool isOld() const
    {
	const BObolViewController *controller = host.getController();
	return !host.isOpen() && window_desc_matches(host.getDesc(), preceding) &&
	    controller->getRenderContextManager() == nullptr &&
	    regionsMatch(initialRegion) &&
	    controller->getLodViewRevision() == initialViewRevision &&
	    !controller->isRenderRequested() &&
	    !controller->hasProgressiveWorkPending();
    }

    bool isComplete() const
    {
	const BObolViewController *controller = host.getController();
	return host.isOpen() && window_desc_matches(host.getDesc(), committed) &&
	    host.getContextManager() != nullptr &&
	    controller->getRenderContextManager() == host.getContextManager() &&
	    regionsMatch(nextRegion) &&
	    controller->getLodViewRevision() != initialViewRevision &&
	    controller->isRenderRequested() &&
	    controller->getRenderReason() == "viewport-size" &&
	    bool(controller->hasProgressiveWorkPending()) == automatic;
    }

    void open()
    {
	require(host.open(&committed) == 0, "headless context host open");
    }

    static void wake(void *data, const char *reason)
    {
	auto &self =
	    *static_cast<HeadlessOpenContextPublicationFixture *>(data);
	if (!self.armed)
	    return;
	++self.calls;
	self.incoherent = self.incoherent || !self.isComplete() ||
	    std::string_view(reason ? reason : "") != "viewport-size";
	if (self.throwing)
	    throw std::bad_alloc();
    }

    BObolHeadlessWindowHost host;
    bool automatic = false;
    BObolWindowDesc preceding;
    BObolWindowDesc committed;
    SbViewportRegion initialRegion;
    SbViewportRegion nextRegion;
    uint64_t initialViewRevision = 0;
    size_t calls = 0;
    bool armed = false;
    bool incoherent = false;
    bool throwing = false;
};

