    static void observe(void *data, SoSensor *)
    {
	auto &self = *static_cast<FramebufferCloseObserver *>(data);
	++self.calls;
	self.incoherent = self.incoherent || !self.fixture.isComplete();
	if (self.throwing)
	    throw std::bad_alloc();
    }

    FramebufferCloseFixture &fixture;
    std::vector<std::unique_ptr<SoNodeSensor>> nodes;
