static RtImagePublicationResult
exercise_rt_image_activation(bool automatic)
{
    RtImageActivationFixture measured(automatic);
    RtImageActivationObserver measuredObserver(measured);
    bool failed = false;
    int result = 0;
    const size_t attempts = invoke_with_failure(
	[&] { result = measured.activate(); },
	std::numeric_limits<size_t>::max(), failed);
    require(!failed && attempts > 0 && result && measured.isComplete() &&
	measuredObserver.calls > 1 && !measured.incoherent,
	"RT activation did not attach one complete image generation");

    const size_t observerCalls = measuredObserver.calls;
    const size_t noOpAttempts = invoke_with_failure(
	[&] { result = measured.activate(); }, 0, failed);
    require(!failed && result && noOpAttempts == 0 &&
	measured.isComplete() && measuredObserver.calls == observerCalls,
	"unchanged RT activation allocated, changed or notified");
    return {};
}

static RtImagePublicationResult
exercise_rt_image_publication(bool automatic, const RtImageExpected &expected,
    const RtImageExpected &final)
{
    RtImagePublicationFixture measured(automatic);
    measured.expected = &expected;
    measured.final = &final;
    RtImagePublicationObserver measuredObserver(measured);
    bool failed = false;
    int result = BV_DISPLAY_PROPERTY_UNSUPPORTED;
    const size_t attempts = invoke_with_failure(
	[&] { result = measured.publish(); },
	std::numeric_limits<size_t>::max(), failed);
    require(!failed && result == BV_DISPLAY_PROPERTY_OK &&
	measured.isComplete() &&
	measuredObserver.calls > 1 && !measured.incoherent,
	"RT image did not publish one complete generation");

    const size_t observerCalls = measuredObserver.calls;
    const size_t noOpAttempts = invoke_with_failure(
	[&] { result = measured.publish(); }, 0, failed);
    require(!failed && result == BV_DISPLAY_PROPERTY_OK &&
	noOpAttempts == 0 && measured.expected->sourceState.matches(
	    *measured.source) && measured.expected->viewportState.matches(
	    *measured.viewport) && measured.samplesAre(2u) &&
	measuredObserver.calls == observerCalls,
	"unchanged RT image policy allocated, changed or notified");

    size_t preserved = 0;
    size_t committedCount = 0;
    for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
	RtImagePublicationFixture fixture(automatic);
	fixture.expected = &expected;
	fixture.final = &final;
	RtImagePublicationObserver observer(fixture);
	failed = false;
	result = BV_DISPLAY_PROPERTY_UNSUPPORTED;
	invoke_with_failure([&] { result = fixture.publish(); }, failAfter,
	    failed);
	const bool old = fixture.isOld();
	require(old || fixture.isComplete(),
	    "RT image retained a partial source or viewport generation");
	require(!fixture.incoherent,
	    "RT image observer saw a partial generation");
	if (old) {
	    ++preserved;
	    require(!observer.calls &&
		result != BV_DISPLAY_PROPERTY_OK,
		"failed RT image publication changed or notified old state");
	    result = fixture.publish();
	    require(result == BV_DISPLAY_PROPERTY_OK,
		"RT image publication retry return");
	} else {
	    ++committedCount;
	}
	require(fixture.isComplete(),
	    "RT image publication retry did not complete");
    }

    RtImagePublicationFixture throwing(automatic);
    throwing.expected = &expected;
    throwing.final = &final;
    RtImagePublicationObserver throwingObserver(throwing);
    throwing.throwing = true;
    failed = false;
    try { (void)throwing.publish(); }
    catch (const std::bad_alloc &) { failed = true; }
    require(failed && throwing.isComplete() &&
	throwingObserver.completeCalls > 1 && !throwing.incoherent &&
	!SoDB::isNotifying(),
	"RT image callback failure interrupted publication");

    RtImagePublicationFixture reentrant(automatic);
    reentrant.expected = &expected;
    reentrant.final = &final;
    RtImagePublicationReentry reentry(reentrant);
    require(reentrant.publish() == BV_DISPLAY_PROPERTY_OK &&
	reentry.triggered && reentry.calls > 1 && !reentry.incoherent &&
	reentrant.finalExpected && reentrant.isComplete() &&
	!reentrant.incoherent,
	"RT image reentry did not retain the later generation");

    return {attempts + 1, preserved, committedCount};
}

static void
check_rt_image_publication()
{
    for (bool automatic : {false, true}) {
	RtImagePublicationFixture warmup(automatic);
	(void)warmup.publish();
    }

    RtImagePublicationFixture reference(false);
    require(reference.publish() == BV_DISPLAY_PROPERTY_OK,
	"RT image reference return");
    RtImageExpected expected(*reference.source, *reference.viewport);
    require(reference.publishFinal() == BV_DISPLAY_PROPERTY_OK,
	"RT image final reference return");
    RtImageExpected final(*reference.source, *reference.viewport);

    RtImagePublicationResult total;
    for (bool automatic : {false, true}) {
	const RtImagePublicationResult activation =
	    exercise_rt_image_activation(automatic);
	const RtImagePublicationResult result =
	    exercise_rt_image_publication(automatic, expected, final);
	total.positions += activation.positions + result.positions;
	total.preserved += activation.preserved + result.preserved;
	total.committed += activation.committed + result.committed;
    }
    std::printf("PASS rt-image-publication: 2 observed activations; %zu restart ordinary/automatic allocation positions, %zu preserved, %zu committed\n",
	 total.positions, total.preserved, total.committed);
}

struct RendererEngineTransition {
    enum bobol_render_engine initial;
    enum bobol_render_engine target;
};

struct RendererEngineFixture {
    RendererEngineFixture(const RendererEngineTransition &transition,
	bool automaticLod) :
	endpoint(bobol_display_endpoint_create(&controller, 0)),
	extensionOwner(retain_node(new SoCube)), target(transition.target)
    {
	require(endpoint != nullptr, "renderer engine initial endpoint");
	if (automaticLod) {
	    struct bv_lod_policy policy;
	    bv_lod_policy_init(&policy);
	    policy.policy = BV_LOD_AUTO;
	    policy.mesh_enabled = policy.csg_enabled = 1;
	    controller.setViewLodPolicy(&policy);
	    controller.setLodAutoSubmit(TRUE);
	}
	controller.setViewportSize(RtImagePublicationFixture::ViewportWidth,
	    RtImagePublicationFixture::ViewportHeight);
	require(bobol_display_endpoint_resize(endpoint.get(),
		RtImagePublicationFixture::ViewportWidth,
		RtImagePublicationFixture::ViewportHeight, 1.0),
	    "renderer engine initial dimensions");
	root = controller.getFramebufferInterlayRoot();
	require(root != nullptr, "renderer engine initial root");
	root->addChild(extensionOwner.get());
	require(transition.initial == BOBOL_RENDER_ENGINE_AUTO ||
	    bobol_display_endpoint_render_engine_set(endpoint.get(),
		transition.initial), "renderer engine initial policy");
	controller.clearRenderRequest();
	extensionPath = make_test_path(root,
	    transition.initial == BOBOL_RENDER_ENGINE_RT ? 1 : 0);
	require(stateMatches(transition.initial),
	    "renderer engine initial state");
    }

    int publish()
    {
	return bobol_display_endpoint_render_engine_set(endpoint.get(), target);
    }

    bool stateMatches(enum bobol_render_engine engine) const
    {
	const bool graphical = engine != BOBOL_RENDER_ENGINE_NONE &&
	    engine != BOBOL_RENDER_ENGINE_DIAGNOSTIC;
	if (bobol_display_endpoint_render_engine_get(endpoint.get()) != engine ||
	    (controller.getRenderRoot() != nullptr) != graphical)
	    return false;
	SoBRLViewportImage *viewport =
	    RtLayerCompositionFixture::findViewport(root);
	if (engine == BOBOL_RENDER_ENGINE_RT) {
	    SoBRLImageSource *source = viewport ? viewport->getImageSource() :
		nullptr;
	    return viewport && source &&
		framebuffer_children_match(root,
		    {viewport, extensionOwner.get()}) &&
		viewport->getNumChildren() == 1 &&
		viewport->getTextureNode() && viewport->getImageFaceSet() &&
		viewport->realizedDataRevision.getValue() ==
		    source->dataRevision.getValue() &&
		viewport->realizedDirtyRevision.getValue() ==
		    source->dirtyRevision.getValue() &&
		extensionPath->getLength() == 2 &&
		extensionPath->getTail() == extensionOwner.get() &&
		extensionPath->getIndex(1) == 1;
	}
	return !viewport && framebuffer_children_match(root,
		{extensionOwner.get()}) && extensionPath->getLength() == 2 &&
	    extensionPath->getTail() == extensionOwner.get() &&
	    extensionPath->getIndex(1) == 0;
    }

    BObolViewController controller;
    std::unique_ptr<bobol_display_endpoint_t, TestDisplayEndpointCloser>
	endpoint;
    TestNodeRef extensionOwner;
    SoGroup *root = nullptr;
    TestPathRef extensionPath;
    enum bobol_render_engine target;
};

struct RendererEngineObserver {
    RendererEngineObserver(RendererEngineFixture &target,
	enum bobol_render_engine expected) :
	fixture(target), expectedEngine(expected), root(observe, this),
	path(observe, this)
    {
	root.setPriority(0);
	path.setPriority(0);
	root.attach(fixture.root);
	path.attach(fixture.extensionPath.get());
    }

    static void observe(void *data, SoSensor *)
    {
	auto &self = *static_cast<RendererEngineObserver *>(data);
	++self.calls;
	if (self.reentryEngine != BOBOL_RENDER_ENGINE_AUTO &&
	    !self.reentered) {
	    self.reentered = true;
	    self.expectedEngine = self.reentryEngine;
	    require(bobol_display_endpoint_render_engine_set(
		    self.fixture.endpoint.get(), self.reentryEngine),
		"renderer engine reentry return");
	}
	self.incoherent = self.incoherent ||
	    !self.fixture.stateMatches(self.expectedEngine);
	if (self.throwing)
	    throw std::bad_alloc();
    }

    RendererEngineFixture &fixture;
    enum bobol_render_engine expectedEngine;
    enum bobol_render_engine reentryEngine = BOBOL_RENDER_ENGINE_AUTO;
    SoNodeSensor root;
    SoPathSensor path;
    size_t calls = 0;
    bool incoherent = false;
    bool throwing = false;
    bool reentered = false;
};

static void
check_renderer_engine_publication()
{
    const RendererEngineTransition transitions[] = {
	{BOBOL_RENDER_ENGINE_AUTO, BOBOL_RENDER_ENGINE_RT},
	{BOBOL_RENDER_ENGINE_NONE, BOBOL_RENDER_ENGINE_RT},
	{BOBOL_RENDER_ENGINE_DIAGNOSTIC, BOBOL_RENDER_ENGINE_RT},
	{BOBOL_RENDER_ENGINE_RT, BOBOL_RENDER_ENGINE_SW},
	{BOBOL_RENDER_ENGINE_RT, BOBOL_RENDER_ENGINE_NONE},
	{BOBOL_RENDER_ENGINE_RT, BOBOL_RENDER_ENGINE_DIAGNOSTIC},
	{BOBOL_RENDER_ENGINE_SW, BOBOL_RENDER_ENGINE_NONE},
	{BOBOL_RENDER_ENGINE_NONE, BOBOL_RENDER_ENGINE_SW},
	{BOBOL_RENDER_ENGINE_SW, BOBOL_RENDER_ENGINE_DIAGNOSTIC},
	{BOBOL_RENDER_ENGINE_DIAGNOSTIC, BOBOL_RENDER_ENGINE_SW},
	{BOBOL_RENDER_ENGINE_SW, BOBOL_RENDER_ENGINE_HW},
	{BOBOL_RENDER_ENGINE_HW, BOBOL_RENDER_ENGINE_AUTO}
    };
    size_t positions = 0;
    size_t preserved = 0;
    size_t committed = 0;
    for (bool automatic : {false, true}) {
	for (const RendererEngineTransition &transition : transitions) {
	    RendererEngineFixture measured(transition, automatic);
	    RendererEngineObserver measuredObserver(measured,
		transition.target);
	    bool failed = false;
	    int result = 0;
	    const size_t attempts = invoke_with_failure(
		[&] { result = measured.publish(); },
		std::numeric_limits<size_t>::max(), failed);
	    require(!failed && result &&
		measured.stateMatches(transition.target) &&
		!measuredObserver.incoherent,
		"renderer engine selection did not complete");

	    if (transition.target != BOBOL_RENDER_ENGINE_DIAGNOSTIC) {
		const size_t observerCalls = measuredObserver.calls;
		const size_t noOpAttempts = invoke_with_failure(
		    [&] { result = measured.publish(); }, 0, failed);
		require(!failed && result && noOpAttempts == 0 &&
		    measured.stateMatches(transition.target) &&
		    measuredObserver.calls == observerCalls,
		    "unchanged renderer engine selection allocated or notified");
	    }

	    for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
		RendererEngineFixture fixture(transition, automatic);
		RendererEngineObserver observer(fixture, transition.target);
		failed = false;
		result = 0;
		invoke_with_failure([&] { result = fixture.publish(); },
		    failAfter, failed);
		const bool old = fixture.stateMatches(transition.initial);
		require(old || fixture.stateMatches(transition.target),
		    "renderer engine selection retained a partial generation");
		require(!observer.incoherent,
		    "renderer engine observer saw a partial generation");
		if (old) {
		    ++preserved;
		    require(!result && !observer.calls,
			"rejected renderer engine selection changed or notified");
		    result = fixture.publish();
		    require(result, "renderer engine selection retry return");
		} else {
		    ++committed;
		    if (failed) {
			result = fixture.publish();
			require(result,
			    "committed renderer engine retry return");
		    }
		}
		require(fixture.stateMatches(transition.target),
		    "renderer engine selection retry did not complete");
		if (transition.target != BOBOL_RENDER_ENGINE_DIAGNOSTIC) {
		    const size_t observerCalls = observer.calls;
		    failed = false;
		    const size_t noOpAttempts = invoke_with_failure(
			[&] { result = fixture.publish(); }, 0, failed);
		    require(!failed && result && noOpAttempts == 0 &&
			fixture.stateMatches(transition.target) &&
			observer.calls == observerCalls,
			"settled renderer engine retry did not become a no-op");
		}
	    }
	    positions += attempts + 1;
	}
    }

    const RendererEngineTransition activation = {
	BOBOL_RENDER_ENGINE_AUTO, BOBOL_RENDER_ENGINE_RT};
    RendererEngineFixture throwing(activation, false);
    RendererEngineObserver throwingObserver(throwing,
	BOBOL_RENDER_ENGINE_RT);
    throwingObserver.throwing = true;
    bool failed = false;
    try { (void)throwing.publish(); }
    catch (const std::bad_alloc &) { failed = true; }
    require(failed && throwing.stateMatches(BOBOL_RENDER_ENGINE_RT) &&
	throwingObserver.calls > 1 && !throwingObserver.incoherent &&
	!SoDB::isNotifying(),
	"renderer engine callback failure interrupted publication");

    RendererEngineFixture reentrant(activation, false);
    RendererEngineObserver reentryObserver(reentrant,
	BOBOL_RENDER_ENGINE_RT);
    reentryObserver.reentryEngine = BOBOL_RENDER_ENGINE_SW;
    require(reentrant.publish() && reentryObserver.reentered &&
	reentryObserver.calls > 1 && !reentryObserver.incoherent &&
	reentrant.stateMatches(BOBOL_RENDER_ENGINE_SW) && !SoDB::isNotifying(),
	"renderer engine callback reentry did not retain the successor");

    const RendererEngineTransition removal = {
	BOBOL_RENDER_ENGINE_RT, BOBOL_RENDER_ENGINE_SW};
    RendererEngineFixture removalThrowing(removal, false);
    RendererEngineObserver removalThrowingObserver(removalThrowing,
	BOBOL_RENDER_ENGINE_SW);
    removalThrowingObserver.throwing = true;
    failed = false;
    try { (void)removalThrowing.publish(); }
    catch (const std::bad_alloc &) { failed = true; }
    require(failed && removalThrowing.stateMatches(BOBOL_RENDER_ENGINE_SW) &&
	removalThrowingObserver.calls > 1 &&
	!removalThrowingObserver.incoherent && !SoDB::isNotifying(),
	"renderer engine removal callback interrupted publication");

    RendererEngineFixture removalReentrant(removal, false);
    RendererEngineObserver removalReentryObserver(removalReentrant,
	BOBOL_RENDER_ENGINE_SW);
    removalReentryObserver.reentryEngine = BOBOL_RENDER_ENGINE_RT;
    require(removalReentrant.publish() &&
	removalReentryObserver.reentered && removalReentryObserver.calls > 1 &&
	!removalReentryObserver.incoherent &&
	removalReentrant.stateMatches(BOBOL_RENDER_ENGINE_RT) &&
	!SoDB::isNotifying(),
	"renderer engine removal reentry did not retain the successor");

    std::printf("PASS renderer-engine-publication: %zu ordinary/automatic allocation positions across %zu transitions, %zu preserved, %zu committed\n",
	positions, sizeof(transitions) / sizeof(transitions[0]), preserved,
	committed);
}

enum class EndpointControllerOwnership { Owned, Borrowed };

struct EndpointDestructionObserver {
    static void changed(void *data, SoSensor *)
    {
	auto &self = *static_cast<EndpointDestructionObserver *>(data);
	++self.calls;
	if (self.reentrant) {
	    if (self.destroyFirst)
		bobol_display_endpoint_destroy(self.endpoint);
	    self.mutationRejected =
		!bobol_display_endpoint_render_engine_set(
		    self.endpoint, BOBOL_RENDER_ENGINE_SW);
	    if (!self.destroyFirst)
		bobol_display_endpoint_destroy(self.endpoint);
	}
	if (self.throwing)
	    throw std::bad_alloc();
    }

    bobol_display_endpoint_t *endpoint = nullptr;
    size_t calls = 0;
    bool throwing = false;
    bool reentrant = false;
    bool destroyFirst = false;
    bool mutationRejected = false;
};

struct EndpointDestructionFixture {
    EndpointDestructionFixture(enum bobol_render_engine selectedEngine,
	EndpointControllerOwnership ownership) :
	borrowedController(ownership == EndpointControllerOwnership::Borrowed ?
	    std::make_unique<BObolViewController>() : nullptr),
	engine(selectedEngine), borrowed(borrowedController != nullptr)
    {
	endpoint = bobol_display_endpoint_create(borrowedController.get(),
	    borrowed ? 0 : BOBOL_ENDPOINT_OWN_CONTROLLER);
	require(endpoint != nullptr, "endpoint destruction initial endpoint");
	controller = static_cast<BObolViewController *>(
	    bobol_display_endpoint_controller(endpoint));
	require(controller != nullptr, "endpoint destruction controller");
	controller->setViewportSize(RtImagePublicationFixture::ViewportWidth,
	    RtImagePublicationFixture::ViewportHeight);
	require(engine == BOBOL_RENDER_ENGINE_AUTO ||
	    bobol_display_endpoint_render_engine_set(endpoint, engine),
	    "endpoint destruction initial engine");
	root = controller->getFramebufferInterlayRoot();
	require(root != nullptr, "endpoint destruction interlay root");
	if (engine == BOBOL_RENDER_ENGINE_RT) {
	    viewport = RtLayerCompositionFixture::findViewport(root);
	    source = viewport ? viewport->getImageSource() : nullptr;
	    require(viewport && source && source->ownsStream(),
		"endpoint destruction self-contained RT graph");
	    viewport->ref();
	    source->ref();
	}
	controller->beginLodInteraction();
	controller->requestLodCapacityRender("endpoint-destruction");
	(void)controller->consumeRenderRequest(nullptr, nullptr, nullptr);
	controller->markProgressiveWorkPending();
	observer.endpoint = endpoint;
	rootSensor.setPriority(0);
	rootSensor.setFunction(EndpointDestructionObserver::changed);
	rootSensor.setData(&observer);
	rootSensor.attach(root);
    }

    ~EndpointDestructionFixture()
    {
	if (endpoint)
	    bobol_display_endpoint_destroy(endpoint);
	rootSensor.detach();
	if (viewport)
	    viewport->unref();
	if (source)
	    source->unref();
    }

    void destroy()
    {
	bobol_display_endpoint_t *retiring = endpoint;
	bobol_display_endpoint_destroy(retiring);
	endpoint = nullptr;
    }

    bool complete() const
    {
	if (endpoint || SoDB::isNotifying())
	    return false;
	if (viewport) {
	    const bool retained = borrowed &&
		framebuffer_children_match(root, {viewport});
	    const bool detached = !borrowed ||
		framebuffer_children_match(root, {});
	    if (!source || !source->ownsStream() || !source->getStream() ||
		source->getRefCount() != 2 || (!retained && !detached) ||
		viewport->getRefCount() != (retained ? 2 : 1))
		return false;
	}
	if (!borrowed)
	    return true;
	return controller->getHostWorkSnapshot().flags ==
		BOBOL_HOST_WORK_NONE &&
	    !controller->isLodGestureActive() &&
	    !controller->isLodInteractionActive() &&
	    controller->getRenderRoot() != nullptr &&
	    controller->getRenderContextManager() == nullptr;
    }

    bool settleController()
    {
	if (!borrowed)
	    return true;
	bobol_display_endpoint_t *replacement =
	    bobol_display_endpoint_create(controller, 0);
	if (!replacement)
	    return false;
	const bool synchronized = controller->getRenderManager() &&
	    controller->getRenderManager()->getSceneGraph() ==
		controller->getRenderRoot();
	bobol_display_endpoint_destroy(replacement);
	return synchronized;
    }

    std::unique_ptr<BObolViewController> borrowedController;
    bobol_display_endpoint_t *endpoint = nullptr;
    BObolViewController *controller = nullptr;
    SoGroup *root = nullptr;
    SoBRLViewportImage *viewport = nullptr;
    SoBRLImageSource *source = nullptr;
    SoNodeSensor rootSensor;
    EndpointDestructionObserver observer;
    enum bobol_render_engine engine;
    bool borrowed;
};

static void
endpoint_destruction_terminated()
{
    std::fprintf(stderr,
	"compact publication: endpoint destructor propagated terminal cleanup failure\n");
    std::fflush(stderr);
    std::_Exit(42);
}

static void
check_endpoint_destruction()
{
    const std::terminate_handler previousTerminate =
	std::set_terminate(endpoint_destruction_terminated);

    {
	BObolViewController controller;
	auto endpoint = std::make_unique<BObolDisplayEndpoint>(&controller,
	    false);
	require(endpoint->isValid() && endpoint->setRenderEngine(
		BOBOL_RENDER_ENGINE_RT),
	    "endpoint destructor callback fixture");
	EndpointDestructionObserver observer;
	observer.endpoint = endpoint->get();
	observer.throwing = true;
	SoNodeSensor sensor(EndpointDestructionObserver::changed, &observer);
	sensor.setPriority(0);
	sensor.attach(controller.getFramebufferInterlayRoot());
	endpoint.reset();
	require(observer.calls && !SoDB::isNotifying(),
	    "endpoint destructor propagated or stranded a root callback");
    }

    {
	EndpointDestructionFixture fixture(BOBOL_RENDER_ENGINE_RT,
	    EndpointControllerOwnership::Borrowed);
	fixture.observer.reentrant = true;
	fixture.destroy();
	require(fixture.complete() && fixture.observer.calls &&
	    fixture.observer.mutationRejected && fixture.settleController(),
	    "endpoint destructor callback reentry changed a closing endpoint");
    }

    {
	BObolViewController controller;
	bobol_display_endpoint_t *endpoint =
	    bobol_display_endpoint_create(&controller, 0);
	require(endpoint != nullptr,
	    "callback-time endpoint destruction initial endpoint");
	EndpointDestructionObserver observer;
	observer.endpoint = endpoint;
	observer.reentrant = true;
	observer.destroyFirst = true;
	SoGroup *root = controller.getFramebufferInterlayRoot();
	SoNodeSensor sensor(EndpointDestructionObserver::changed, &observer);
	sensor.setPriority(0);
	sensor.attach(root);
	require(bobol_display_endpoint_render_engine_set(endpoint,
		BOBOL_RENDER_ENGINE_RT) && observer.calls &&
	    observer.mutationRejected && framebuffer_children_match(root, {}) &&
	    controller.getHostWorkSnapshot().flags == BOBOL_HOST_WORK_NONE &&
	    !SoDB::isNotifying(),
	    "engine callback endpoint destruction outlived its operation lease");
    }

    {
	BObolLodService service;
	require(service.start(1, FALSE),
	    "endpoint destruction active service startup");
	BObolViewController controller;
	controller.setLodService(&service);
	require(controller.beginLodGeneration() != 0,
	    "endpoint destruction active generation");
	controller.beginLodInteraction();
	controller.requestLodCapacityRender(
	    "endpoint-destruction-active-generation");
	bobol_display_endpoint_t *endpoint =
	    bobol_display_endpoint_create(&controller, 0);
	require(endpoint != nullptr,
	    "endpoint destruction active generation endpoint");
	bool failed = false;
	(void)invoke_with_failure(
	    [&] { bobol_display_endpoint_destroy(endpoint); }, 0, failed);
	require(!failed && controller.getHostWorkSnapshot().flags ==
		BOBOL_HOST_WORK_NONE && !controller.isLodGestureActive() &&
	    !controller.isLodInteractionActive(),
	    "endpoint destruction stranded an allocation-denied LoD owner");
	controller.setLodService(nullptr);
	service.stop();
    }

    size_t positions = 0;
    size_t retainedFallbacks = 0;
    const enum bobol_render_engine engines[] = {
	BOBOL_RENDER_ENGINE_AUTO,
	BOBOL_RENDER_ENGINE_NONE,
	BOBOL_RENDER_ENGINE_DIAGNOSTIC,
	BOBOL_RENDER_ENGINE_RT
    };
    for (EndpointControllerOwnership ownership : {
	EndpointControllerOwnership::Owned,
	EndpointControllerOwnership::Borrowed}) {
	for (enum bobol_render_engine engine : engines) {
	    EndpointDestructionFixture measured(engine, ownership);
	    bool failed = false;
	    const size_t attempts = invoke_with_failure(
		[&] { measured.destroy(); },
		std::numeric_limits<size_t>::max(), failed);
	    require(!failed && measured.complete() &&
		measured.settleController(),
		"endpoint destruction did not reach a terminal state");

	    for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
		EndpointDestructionFixture fixture(engine, ownership);
		failed = false;
		invoke_with_failure([&] { fixture.destroy(); }, failAfter,
		    failed);
		require(!failed && fixture.complete(),
		    "endpoint destruction propagated allocation failure");
		if (fixture.borrowed && fixture.viewport &&
		    framebuffer_children_match(fixture.root,
			{fixture.viewport}))
		    ++retainedFallbacks;
		require(fixture.settleController(),
		    "endpoint destruction retry obligation did not settle");
	    }
	    positions += attempts + 1;
	}
    }

    std::set_terminate(previousTerminate);
    std::printf("PASS endpoint-destruction: %zu owned/borrowed engine allocation positions, %zu self-contained borrowed-root fallbacks, throwing observers and callback reentry complete\n",
	positions, retainedFallbacks);
}

enum class EditManipulatorRebuildKind { Axes, Indexed };

struct EditManipulatorRebuildFixture {
    EditManipulatorRebuildFixture(EditManipulatorRebuildKind rebuildKind,
	    bool clear) :
	kind(rebuildKind), clearing(clear),
	owner(retain_node(kind == EditManipulatorRebuildKind::Axes ?
	    static_cast<SoNode *>(new SoBRLEditManipulator) :
	    static_cast<SoNode *>(new SoBRLIndexedEditManipulator))),
	group(*static_cast<SoSeparator *>(owner.get()))
    {
	if (kind == EditManipulatorRebuildKind::Axes) {
	    auto &manipulator = static_cast<SoBRLEditManipulator &>(group);
	    require(manipulator.getNumChildren() == 4,
		"axis manipulator initial rebuild");
	    manipulator.activeHandle = SoBRLEditManipulator::HANDLE_AXIS_A;
	} else {
	    auto &manipulator =
		static_cast<SoBRLIndexedEditManipulator &>(group);
	    const SbVec3f points[4] = {
		SbVec3f(-1.0f, -1.0f, 0.0f),
		SbVec3f(1.0f, -1.0f, 0.0f),
		SbVec3f(1.0f, 1.0f, 0.0f),
		SbVec3f(-1.0f, 1.0f, 0.0f)
	    };
	    const int32_t edges[8] = {0, 1, 1, 2, 2, 3, 3, 0};
	    manipulator.setTopology(points, 4, edges, 4, nullptr, nullptr, 0);
	    require(manipulator.getNumChildren() == 3,
		"indexed manipulator initial rebuild");
	    manipulator.selectedIndex = 1;
	    manipulator.hoverIndex = 2;
	    manipulator.activeIndex = 3;
	}
	if (clearing) {
	    if (kind == EditManipulatorRebuildKind::Axes)
		static_cast<SoBRLEditManipulator &>(group).visible = FALSE;
	    else
		static_cast<SoBRLIndexedEditManipulator &>(group).visible = FALSE;
	}
	for (int i = 0; i < group.getNumChildren(); ++i) {
	    original.push_back(group.getChild(i));
	    originalOwners.push_back(retain_node(group.getChild(i)));
	    paths.push_back(make_test_path(&group, i));
	}
    }
    void rebuild()
    {
	if (kind == EditManipulatorRebuildKind::Axes)
	    static_cast<SoBRLEditManipulator &>(group).rebuildGeometry();
	else
	    static_cast<SoBRLIndexedEditManipulator &>(group).rebuildGeometry();
    }
    bool pathsOld() const
    {
	for (size_t i = 0; i < paths.size(); ++i)
	    if (paths[i]->getLength() != 2 || paths[i]->getTail() != original[i] ||
		paths[i]->getIndex(1) != int(i))
		return false;
	return true;
    }
    bool isOld() const
    {
	if (size_t(group.getNumChildren()) != original.size() || !pathsOld())
	    return false;
	for (size_t i = 0; i < original.size(); ++i)
	    if (group.getChild(int(i)) != original[i]) return false;
	return true;
    }
    bool childGroupHasCount(int index, int count) const
    {
	if (index < 0 || index >= group.getNumChildren()) return false;
	SoNode *node = group.getChild(index);
	return node && node->isOfType(SoGroup::getClassTypeId()) &&
	    static_cast<SoGroup *>(node)->getNumChildren() == count;
    }
    bool isComplete() const
    {
	for (const auto &path : paths)
	    if (path->getLength() != 1) return false;
	if (clearing)
	    return group.getNumChildren() == 0;
	for (int i = 0; i < group.getNumChildren(); ++i)
	    if (std::find(original.begin(), original.end(), group.getChild(i)) !=
		original.end())
		return false;
	if (!group.getNumChildren() ||
	    !group.getChild(0)->isOfType(SoLightModel::getClassTypeId()))
	    return false;
	if (kind == EditManipulatorRebuildKind::Axes) {
	    if (group.getNumChildren() != 4 || !childGroupHasCount(1, 5) ||
		!childGroupHasCount(2, 5) || !childGroupHasCount(3, 5))
		return false;
	    auto *axis = static_cast<SoGroup *>(group.getChild(1));
	    SoNode *styleNode = axis->getChild(1);
	    return styleNode && styleNode->isOfType(SoDrawStyle::getClassTypeId()) &&
		std::fabs(static_cast<SoDrawStyle *>(styleNode)->lineWidth.getValue() -
		    4.0f) <= std::numeric_limits<float>::epsilon();
	}
	return group.getNumChildren() == 6 && childGroupHasCount(1, 4) &&
	    childGroupHasCount(2, 4) && childGroupHasCount(3, 4) &&
	    childGroupHasCount(4, 4) && childGroupHasCount(5, 4);
    }

    EditManipulatorRebuildKind kind;
    bool clearing;
    TestNodeRef owner;
    SoSeparator &group;
    std::vector<SoNode *> original;
    std::vector<TestNodeRef> originalOwners;
    std::vector<TestPathRef> paths;
};

struct EditManipulatorRebuildObserver {
    explicit EditManipulatorRebuildObserver(
	    EditManipulatorRebuildFixture &target) :
	fixture(target), node(observe, this)
    {
	node.setPriority(0);
	node.attach(&fixture.group);
	for (auto &path : fixture.paths) {
	    auto sensor = std::make_unique<SoPathSensor>(observe, this);
	    sensor->setPriority(0);
	    sensor->attach(path.get());
	    paths.push_back(std::move(sensor));
	}
    }
    static void observe(void *data, SoSensor *)
    {
	auto &self = *static_cast<EditManipulatorRebuildObserver *>(data);
	++self.calls;
	self.incoherent = self.incoherent || !self.fixture.isComplete();
	if (self.throwing) throw std::bad_alloc();
    }

    EditManipulatorRebuildFixture &fixture;
    SoNodeSensor node;
    std::vector<std::unique_ptr<SoPathSensor>> paths;
    size_t calls = 0;
    bool incoherent = false;
    bool throwing = false;
};

static void
check_edit_manipulator_rebuild_publication()
{
    size_t positions = 0, preserved = 0, committed = 0;
    for (EditManipulatorRebuildKind kind : {
	EditManipulatorRebuildKind::Axes,
	EditManipulatorRebuildKind::Indexed}) {
	for (bool clearing : {false, true}) {
	    EditManipulatorRebuildFixture measured(kind, clearing);
	    EditManipulatorRebuildObserver measuredObserver(measured);
	    bool failed = false;
	    const size_t attempts = invoke_with_failure([&] {
		measured.rebuild();
	    }, std::numeric_limits<size_t>::max(), failed);
	    require(!failed && measured.isComplete() && measuredObserver.calls &&
		!measuredObserver.incoherent,
		"edit manipulator rebuild exposed partial children");
	    positions += attempts + 1;

	    if (clearing) {
		const size_t calls = measuredObserver.calls;
		failed = false;
		const size_t repeatedAttempts = invoke_with_failure([&] {
		    measured.rebuild();
		}, 0, failed);
		require(!failed && repeatedAttempts == 0 && measured.isComplete() &&
		    measuredObserver.calls == calls,
		    "repeated hidden edit manipulator rebuild allocated, changed or notified");
	    }

	    for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
		EditManipulatorRebuildFixture fixture(kind, clearing);
		EditManipulatorRebuildObserver observer(fixture);
		failed = false;
		invoke_with_failure([&] { fixture.rebuild(); }, failAfter, failed);
		const bool old = fixture.isOld();
		require(old || fixture.isComplete(),
		    "edit manipulator rebuild left partial children");
		require(!observer.incoherent,
		    "edit manipulator observer saw partial children");
		if (old) {
		    ++preserved;
		    require(failed && !observer.calls,
			"failed edit manipulator rebuild changed or notified the old state");
		    fixture.rebuild();
		} else {
		    ++committed;
		}
		require(fixture.isComplete(),
		    "edit manipulator rebuild retry did not complete");
	    }

	    EditManipulatorRebuildFixture throwing(kind, clearing);
	    EditManipulatorRebuildObserver observer(throwing);
	    observer.throwing = true;
	    failed = false;
	    try { throwing.rebuild(); }
	    catch (const std::bad_alloc &) { failed = true; }
	    require(failed && throwing.isComplete() && observer.calls > 1 &&
		!observer.incoherent && !SoDB::isNotifying(),
		"edit manipulator callback failure interrupted rebuild or notifications");
	}
    }
    std::printf("PASS edit-manipulator-rebuild-publication: %zu allocation positions, %zu preserved, %zu committed\n",
	positions, preserved, committed);
}

enum class EditManipulatorSetterKind {
    AxisGeometry,
    AxisHover,
    AxisVisible,
    IndexedTopology,
    IndexedDomain,
    IndexedHover,
    IndexedVisible
};

struct EditManipulatorSetterFixture {
    explicit EditManipulatorSetterFixture(EditManipulatorSetterKind setterKind) :
	kind(setterKind), axis(kind == EditManipulatorSetterKind::AxisGeometry ||
	    kind == EditManipulatorSetterKind::AxisHover ||
	    kind == EditManipulatorSetterKind::AxisVisible),
	owner(retain_node(axis ? static_cast<SoNode *>(new SoBRLEditManipulator) :
	    static_cast<SoNode *>(new SoBRLIndexedEditManipulator))),
	group(*static_cast<SoSeparator *>(owner.get()))
    {
	if (axis) {
	    auto &manipulator = static_cast<SoBRLEditManipulator &>(group);
	    manipulator.setEllipsoidAxes(oldCenter, oldAxes[0], oldAxes[1],
		oldAxes[2]);
	} else {
	    auto &manipulator =
		static_cast<SoBRLIndexedEditManipulator &>(group);
	    manipulator.setTopology(oldPoints, 4, oldEdges, 4, oldFaces,
		oldFaceCounts, 1);
	    if (kind == EditManipulatorSetterKind::IndexedTopology) {
		manipulator.setSelectionDomain(
		    SoBRLIndexedEditManipulator::DOMAIN_FACE);
		manipulator.setSelectedIndex(0);
	    } else if (kind == EditManipulatorSetterKind::IndexedDomain) {
		manipulator.setSelectedIndex(1);
		manipulator.setHoverIndex(2);
		manipulator.setActiveIndex(3);
	    }
	}
	for (int i = 0; i < group.getNumChildren(); ++i) {
	    original.push_back(group.getChild(i));
	    originalOwners.push_back(retain_node(group.getChild(i)));
	    paths.push_back(make_test_path(&group, i));
	}
    }
    void change()
    {
	if (axis) {
	    auto &manipulator = static_cast<SoBRLEditManipulator &>(group);
	    if (kind == EditManipulatorSetterKind::AxisGeometry)
		manipulator.setEllipsoidAxes(nextCenter, nextAxes[0], nextAxes[1],
		    nextAxes[2]);
	    else if (kind == EditManipulatorSetterKind::AxisHover)
		manipulator.setHoverHandle(SoBRLEditManipulator::HANDLE_AXIS_A);
	    else
		manipulator.setVisible(FALSE);
	    return;
	}

	auto &manipulator =
	    static_cast<SoBRLIndexedEditManipulator &>(group);
	if (kind == EditManipulatorSetterKind::IndexedTopology)
	    manipulator.setTopology(nextPoints, 3, nextEdges, 2, nullptr,
		nullptr, 0);
	else if (kind == EditManipulatorSetterKind::IndexedDomain)
	    manipulator.setSelectionDomain(
		SoBRLIndexedEditManipulator::DOMAIN_FACE);
	else if (kind == EditManipulatorSetterKind::IndexedHover)
	    manipulator.setHoverIndex(2);
	else
	    manipulator.setVisible(FALSE);
    }
    bool pathsOld() const
    {
	for (size_t i = 0; i < paths.size(); ++i)
	    if (paths[i]->getLength() != 2 || paths[i]->getTail() != original[i] ||
		paths[i]->getIndex(1) != int(i))
		return false;
	return true;
    }
    bool oldChildren() const
    {
	if (size_t(group.getNumChildren()) != original.size() || !pathsOld())
	    return false;
	for (size_t i = 0; i < original.size(); ++i)
	    if (group.getChild(int(i)) != original[i])
		return false;
	return true;
    }
    bool newChildren(int expectedCount) const
    {
	for (const auto &path : paths)
	    if (path->getLength() != 1)
		return false;
	if (group.getNumChildren() != expectedCount)
	    return false;
	for (int i = 0; i < group.getNumChildren(); ++i)
	    if (std::find(original.begin(), original.end(), group.getChild(i)) !=
		original.end())
		return false;
	return true;
    }
    bool isOld() const
    {
	if (!oldChildren())
	    return false;
	if (axis) {
	    const auto &manipulator =
		static_cast<const SoBRLEditManipulator &>(group);
	    return manipulator.visible.getValue() &&
		manipulator.hoverHandle.getValue() ==
		    SoBRLEditManipulator::HANDLE_NONE &&
		manipulator.center() == oldCenter &&
		manipulator.axis(SoBRLEditManipulator::HANDLE_AXIS_A) == oldAxes[0];
	}

	const auto &manipulator =
	    static_cast<const SoBRLIndexedEditManipulator &>(group);
	SbVec3f position;
	if (manipulator.pointCount() != 4 || manipulator.edgeCount() != 4 ||
	    manipulator.faceCount() != 1 ||
	    !manipulator.featurePosition(
		SoBRLIndexedEditManipulator::DOMAIN_VERTEX, 0, position) ||
	    position != oldPoints[0] || !manipulator.visible.getValue())
	    return false;
	if (kind == EditManipulatorSetterKind::IndexedTopology)
	    return manipulator.selectionDomain.getValue() ==
		SoBRLIndexedEditManipulator::DOMAIN_FACE &&
		manipulator.selectedIndex.getValue() == 0;
	if (kind == EditManipulatorSetterKind::IndexedDomain)
	    return manipulator.selectionDomain.getValue() ==
		SoBRLIndexedEditManipulator::DOMAIN_VERTEX &&
		manipulator.selectedIndex.getValue() == 1 &&
		manipulator.hoverIndex.getValue() == 2 &&
		manipulator.activeIndex.getValue() == 3;
	return manipulator.selectionDomain.getValue() ==
		SoBRLIndexedEditManipulator::DOMAIN_VERTEX &&
	    manipulator.hoverIndex.getValue() == -1;
    }
    bool isComplete() const
    {
	if (axis) {
	    const auto &manipulator =
		static_cast<const SoBRLEditManipulator &>(group);
	    if (kind == EditManipulatorSetterKind::AxisGeometry)
		return newChildren(4) && manipulator.visible.getValue() &&
		    manipulator.center() == nextCenter &&
		    manipulator.axis(SoBRLEditManipulator::HANDLE_AXIS_A) ==
			nextAxes[0];
	    if (kind == EditManipulatorSetterKind::AxisHover)
		return newChildren(4) && manipulator.hoverHandle.getValue() ==
		    SoBRLEditManipulator::HANDLE_AXIS_A;
	    return newChildren(0) && !manipulator.visible.getValue();
	}

	const auto &manipulator =
	    static_cast<const SoBRLIndexedEditManipulator &>(group);
	if (kind == EditManipulatorSetterKind::IndexedTopology) {
	    SbVec3f position;
	    return newChildren(3) && manipulator.pointCount() == 3 &&
		manipulator.edgeCount() == 2 && manipulator.faceCount() == 0 &&
		manipulator.selectedIndex.getValue() == -1 &&
		manipulator.featurePosition(
		    SoBRLIndexedEditManipulator::DOMAIN_VERTEX, 0, position) &&
		position == nextPoints[0];
	}
	if (kind == EditManipulatorSetterKind::IndexedDomain)
	    return newChildren(3) && manipulator.selectionDomain.getValue() ==
		SoBRLIndexedEditManipulator::DOMAIN_FACE &&
		manipulator.selectedIndex.getValue() == -1 &&
		manipulator.hoverIndex.getValue() == -1 &&
		manipulator.activeIndex.getValue() == -1;
	if (kind == EditManipulatorSetterKind::IndexedHover)
	    return newChildren(4) && manipulator.hoverIndex.getValue() == 2;
	return newChildren(0) && !manipulator.visible.getValue();
    }
    bool hasNoOp() const
    {
	return kind != EditManipulatorSetterKind::AxisGeometry &&
	    kind != EditManipulatorSetterKind::IndexedTopology;
    }

    inline static const SbVec3f oldCenter = SbVec3f(0.0f, 0.0f, 0.0f);
    inline static const SbVec3f oldAxes[3] = {
	SbVec3f(1.0f, 0.0f, 0.0f), SbVec3f(0.0f, 1.0f, 0.0f),
	SbVec3f(0.0f, 0.0f, 1.0f)
    };
    inline static const SbVec3f nextCenter = SbVec3f(2.0f, 3.0f, 4.0f);
    inline static const SbVec3f nextAxes[3] = {
	SbVec3f(2.0f, 0.0f, 0.0f), SbVec3f(0.0f, 3.0f, 0.0f),
	SbVec3f(0.0f, 0.0f, 4.0f)
    };
    inline static const SbVec3f oldPoints[4] = {
	SbVec3f(-1.0f, -1.0f, 0.0f), SbVec3f(1.0f, -1.0f, 0.0f),
	SbVec3f(1.0f, 1.0f, 0.0f), SbVec3f(-1.0f, 1.0f, 0.0f)
    };
    static constexpr int32_t oldEdges[8] = {0, 1, 1, 2, 2, 3, 3, 0};
    static constexpr int32_t oldFaces[4] = {0, 1, 2, 3};
    static constexpr int32_t oldFaceCounts[1] = {4};
    inline static const SbVec3f nextPoints[3] = {
	SbVec3f(10.0f, 0.0f, 0.0f), SbVec3f(11.0f, 0.0f, 0.0f),
	SbVec3f(12.0f, 1.0f, 0.0f)
    };
    static constexpr int32_t nextEdges[4] = {0, 1, 1, 2};

    EditManipulatorSetterKind kind;
    bool axis;
    TestNodeRef owner;
    SoSeparator &group;
    std::vector<SoNode *> original;
    std::vector<TestNodeRef> originalOwners;
    std::vector<TestPathRef> paths;
};

struct EditManipulatorSetterObserver {
    explicit EditManipulatorSetterObserver(
	EditManipulatorSetterFixture &target) : fixture(target), node(observe, this)
    {
	node.setPriority(0);
	node.attach(&fixture.group);
	for (auto &path : fixture.paths) {
	    auto sensor = std::make_unique<SoPathSensor>(observe, this);
	    sensor->setPriority(0);
	    sensor->attach(path.get());
	    paths.push_back(std::move(sensor));
	}
    }
    static void observe(void *data, SoSensor *)
    {
	auto &self = *static_cast<EditManipulatorSetterObserver *>(data);
	++self.calls;
	self.incoherent = self.incoherent || !self.fixture.isComplete();
	if (self.throwing)
	    throw std::bad_alloc();
    }

    EditManipulatorSetterFixture &fixture;
    SoNodeSensor node;
    std::vector<std::unique_ptr<SoPathSensor>> paths;
    size_t calls = 0;
    bool incoherent = false;
    bool throwing = false;
};

static void
check_edit_manipulator_setter_publication()
{
    size_t positions = 0, preserved = 0, committed = 0;
    for (EditManipulatorSetterKind kind : {
	EditManipulatorSetterKind::AxisGeometry,
	EditManipulatorSetterKind::AxisHover,
	EditManipulatorSetterKind::AxisVisible,
	EditManipulatorSetterKind::IndexedTopology,
	EditManipulatorSetterKind::IndexedDomain,
	EditManipulatorSetterKind::IndexedHover,
	EditManipulatorSetterKind::IndexedVisible}) {
	EditManipulatorSetterFixture measured(kind);
	EditManipulatorSetterObserver measuredObserver(measured);
	bool failed = false;
	const size_t attempts = invoke_with_failure([&] { measured.change(); },
	    std::numeric_limits<size_t>::max(), failed);
	require(!failed && measured.isComplete() && measuredObserver.calls &&
	    !measuredObserver.incoherent,
	    "edit manipulator setter exposed partial state");
	positions += attempts + 1;

	if (measured.hasNoOp()) {
	    const size_t calls = measuredObserver.calls;
	    failed = false;
	    const size_t repeatedAttempts = invoke_with_failure(
		[&] { measured.change(); }, 0, failed);
	    require(!failed && repeatedAttempts == 0 && measured.isComplete() &&
		measuredObserver.calls == calls,
		"repeated edit manipulator setter allocated, changed or notified");
	}

	for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
	    EditManipulatorSetterFixture fixture(kind);
	    EditManipulatorSetterObserver observer(fixture);
	    failed = false;
	    invoke_with_failure([&] { fixture.change(); }, failAfter, failed);
	    const bool old = fixture.isOld();
	    require(old || fixture.isComplete(),
		"edit manipulator setter left partial state");
	    require(!observer.incoherent,
		"edit manipulator setter observer saw partial state");
	    if (old) {
		++preserved;
		require(failed && !observer.calls,
		    "failed edit manipulator setter changed or notified old state");
		fixture.change();
	    } else {
		++committed;
	    }
	    require(fixture.isComplete(),
		"edit manipulator setter retry did not complete");
	}

	EditManipulatorSetterFixture throwing(kind);
	EditManipulatorSetterObserver observer(throwing);
	observer.throwing = true;
	failed = false;
	try { throwing.change(); }
	catch (const std::bad_alloc &) { failed = true; }
	require(failed && throwing.isComplete() && observer.calls > 1 &&
	    !observer.incoherent && !SoDB::isNotifying(),
	    "edit manipulator setter callback failure interrupted publication");
    }
    std::printf("PASS edit-manipulator-setter-publication: %zu allocation positions, %zu preserved, %zu committed\n",
	positions, preserved, committed);
}

enum class EditPreviewPublication { Line, Transformed, Clear, Invalid };

struct EditPreviewFixture {
    explicit EditPreviewFixture(EditPreviewPublication operation) :
	kind(operation), owner(retain_node(new SoBRLEditPreview)),
	preview(*static_cast<SoBRLEditPreview *>(owner.get()))
    {
	preview.previewId = "preview::publication";
	preview.editIntentId = "intent::publication";
	preview.sourceRevision = OLD_SOURCE_REVISION;
	preview.inputsRevision = OLD_INPUTS_REVISION;
	const SbVec3f points[2] = {
	    SbVec3f(0.0f, 0.0f, 0.0f), SbVec3f(1.0f, 0.0f, 0.0f)
	};
	const int32_t commands[2] = {
	    SoBRLVListShape::MOVE, SoBRLVListShape::DRAW
	};
	require(preview.setLineSet("preview::old", points, commands, 2),
	    "edit preview initial publication");
	preview.sourceRevision = NEW_SOURCE_REVISION;
	preview.inputsRevision = NEW_INPUTS_REVISION;
	require(preview.needsRealization() &&
	    preview.previewStatus.getValue() == SoBRLEditPreview::STALE,
	    "edit preview initial stale state");
	for (int i = 0; i < preview.getNumChildren(); ++i) {
	    original.push_back(preview.getChild(i));
	    originalOwners.push_back(retain_node(preview.getChild(i)));
	    paths.push_back(make_test_path(&preview, i));
	}
    }
    SoBRLVListShape *publish()
    {
	if (kind == EditPreviewPublication::Clear) {
	    preview.clearPreview();
	    return nullptr;
	}
	if (kind == EditPreviewPublication::Invalid)
	    return preview.setLineSet(invalidIdentity, nullptr, nullptr, 0);
	const SbVec3f points[3] = {
	    SbVec3f(0.0f, 0.0f, 0.0f), SbVec3f(2.0f, 1.0f, 0.0f),
	    SbVec3f(3.0f, 2.0f, 0.0f)
	};
	const int32_t commands[3] = {
	    SoBRLVListShape::MOVE, SoBRLVListShape::DRAW,
	    SoBRLVListShape::DRAW
	};
	if (kind == EditPreviewPublication::Line)
	    return preview.setLineSet("preview::new", points, commands, 3);
	SbMatrix transform;
	transform.setTranslate(SbVec3f(4.0f, 5.0f, 6.0f));
	return preview.setTransformedLineSet("preview::transformed", transform,
	    points, commands, 3);
    }
    bool pathsOld() const
    {
	for (size_t i = 0; i < paths.size(); ++i)
	    if (paths[i]->getLength() != 2 || paths[i]->getTail() != original[i] ||
		paths[i]->getIndex(1) != int(i))
		return false;
	return true;
    }
    bool fieldsOld() const
    {
	return preview.realizedSourceRevision.getValue() == OLD_SOURCE_REVISION &&
	    preview.realizedInputsRevision.getValue() == OLD_INPUTS_REVISION &&
	    preview.previewStatus.getValue() == SoBRLEditPreview::STALE &&
	    preview.stale.getValue() && preview.needsRealization();
    }
    bool isOld() const
    {
	if (!fieldsOld() || size_t(preview.getNumChildren()) != original.size() ||
	    !pathsOld())
	    return false;
	for (size_t i = 0; i < original.size(); ++i)
	    if (preview.getChild(int(i)) != original[i]) return false;
	return true;
    }
    SoBRLVListShape *completeShape() const
    {
	if (preview.getNumChildren() != 1) return nullptr;
	SoNode *child = preview.getChild(0);
	if (kind == EditPreviewPublication::Line)
	    return child->isOfType(SoBRLVListShape::getClassTypeId()) ?
		static_cast<SoBRLVListShape *>(child) : nullptr;
	if (kind != EditPreviewPublication::Transformed ||
	    !child->isOfType(SoGroup::getClassTypeId()))
	    return nullptr;
	auto *root = static_cast<SoGroup *>(child);
	return root->getNumChildren() == 2 &&
	    root->getChild(0)->isOfType(SoMatrixTransform::getClassTypeId()) &&
	    root->getChild(1)->isOfType(SoBRLVListShape::getClassTypeId()) ?
	    static_cast<SoBRLVListShape *>(root->getChild(1)) : nullptr;
    }
    bool isComplete() const
    {
	for (const auto &path : paths)
	    if (path->getLength() != 1) return false;
	if (kind == EditPreviewPublication::Invalid)
	    return preview.getNumChildren() == 0 &&
		preview.realizedSourceRevision.getValue() == OLD_SOURCE_REVISION &&
		preview.realizedInputsRevision.getValue() == OLD_INPUTS_REVISION &&
		preview.previewStatus.getValue() == SoBRLEditPreview::FAILED &&
		preview.stale.getValue() && preview.needsRealization();
	if (kind == EditPreviewPublication::Clear)
	    return preview.getNumChildren() == 0 &&
		preview.realizedSourceRevision.getValue() == NEW_SOURCE_REVISION &&
		preview.realizedInputsRevision.getValue() == NEW_INPUTS_REVISION &&
		preview.previewStatus.getValue() == SoBRLEditPreview::EMPTY &&
		!preview.stale.getValue() && !preview.needsRealization();
	SoBRLVListShape *shape = completeShape();
	return shape &&
	    shape->sourceId.getValue() == NEW_SOURCE_REVISION &&
	    shape->point.getNum() == 3 &&
	    preview.realizedSourceRevision.getValue() == NEW_SOURCE_REVISION &&
	    preview.realizedInputsRevision.getValue() == NEW_INPUTS_REVISION &&
	    preview.previewStatus.getValue() == SoBRLEditPreview::CURRENT &&
	    !preview.stale.getValue() && !preview.needsRealization();
    }

    static constexpr uint32_t OLD_SOURCE_REVISION = 7;
    static constexpr uint32_t OLD_INPUTS_REVISION = 9;
    static constexpr uint32_t NEW_SOURCE_REVISION = 8;
    static constexpr uint32_t NEW_INPUTS_REVISION = 10;
    EditPreviewPublication kind;
    TestNodeRef owner;
    SoBRLEditPreview &preview;
    std::vector<SoNode *> original;
    std::vector<TestNodeRef> originalOwners;
    std::vector<TestPathRef> paths;
    SbString invalidIdentity{"preview::invalid"};
};

struct EditPreviewObserver {
    explicit EditPreviewObserver(EditPreviewFixture &target) :
	fixture(target), node(observe, this)
    {
	node.setPriority(0);
	node.attach(&fixture.preview);
	for (SoField *field : {
	    static_cast<SoField *>(&fixture.preview.realizedSourceRevision),
	    static_cast<SoField *>(&fixture.preview.realizedInputsRevision),
	    static_cast<SoField *>(&fixture.preview.previewStatus),
	    static_cast<SoField *>(&fixture.preview.stale)}) {
	    auto sensor = std::make_unique<SoFieldSensor>(observe, this);
	    sensor->setPriority(0);
	    sensor->attach(field);
	    fields.push_back(std::move(sensor));
	}
	for (auto &path : fixture.paths) {
	    auto sensor = std::make_unique<SoPathSensor>(observe, this);
	    sensor->setPriority(0);
	    sensor->attach(path.get());
	    paths.push_back(std::move(sensor));
	}
    }
    static void observe(void *data, SoSensor *)
    {
	auto &self = *static_cast<EditPreviewObserver *>(data);
	++self.calls;
	self.incoherent = self.incoherent || !self.fixture.isComplete();
	if (self.throwing) throw std::bad_alloc();
    }

    EditPreviewFixture &fixture;
    SoNodeSensor node;
    std::vector<std::unique_ptr<SoFieldSensor>> fields;
    std::vector<std::unique_ptr<SoPathSensor>> paths;
    size_t calls = 0;
    bool incoherent = false;
    bool throwing = false;
};

static void
check_edit_preview_publication()
{
    size_t positions = 0, preserved = 0, committed = 0;
    for (EditPreviewPublication kind : {EditPreviewPublication::Line,
	EditPreviewPublication::Transformed, EditPreviewPublication::Clear,
	EditPreviewPublication::Invalid}) {
	EditPreviewFixture measured(kind);
	EditPreviewObserver measuredObserver(measured);
	bool failed = false;
	const bool expectsShape = kind == EditPreviewPublication::Line ||
	    kind == EditPreviewPublication::Transformed;
	const size_t attempts = invoke_with_failure([&] {
	    require(bool(measured.publish()) == expectsShape,
		"edit preview measured return");
	}, std::numeric_limits<size_t>::max(), failed);
	require(!failed && measured.isComplete() && measuredObserver.calls &&
	    !measuredObserver.incoherent,
	    "edit preview publication exposed partial fields or children");
	positions += attempts + 1;

	if (!expectsShape) {
	    const size_t calls = measuredObserver.calls;
	    failed = false;
	    const size_t repeatedAttempts = invoke_with_failure([&] {
		require(!measured.publish(), "repeated empty edit preview return");
	    }, 0, failed);
	    require(!failed && repeatedAttempts == 0 && measured.isComplete() &&
		measuredObserver.calls == calls,
		"repeated empty edit preview allocated, changed or notified");
	}

	for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
	    EditPreviewFixture fixture(kind);
	    EditPreviewObserver observer(fixture);
	    failed = false;
	    invoke_with_failure([&] {
		require(bool(fixture.publish()) == expectsShape,
		    "edit preview swept return");
	    }, failAfter, failed);
	    const bool old = fixture.isOld();
	    require(old || fixture.isComplete(),
		"edit preview publication left partial fields or children");
	    require(!observer.incoherent,
		"edit preview observer saw partial fields or children");
	    if (old) {
		++preserved;
		require(failed && !observer.calls,
		    "failed edit preview publication changed or notified old state");
		require(bool(fixture.publish()) == expectsShape,
		    "edit preview publication retry return");
	    } else {
		++committed;
	    }
	    require(fixture.isComplete(),
		"edit preview publication retry did not complete");
	}

	EditPreviewFixture throwing(kind);
	EditPreviewObserver observer(throwing);
	observer.throwing = true;
	failed = false;
	try { (void)throwing.publish(); }
	catch (const std::bad_alloc &) { failed = true; }
	require(failed && throwing.isComplete() && observer.calls > 1 &&
	    !observer.incoherent && !SoDB::isNotifying(),
	    "edit preview callback failure interrupted publication or notifications");
    }
    std::printf("PASS edit-preview-publication: %zu allocation positions, %zu preserved, %zu committed\n",
	positions, preserved, committed);
}

enum class ControllerEditPreviewOperation { Insert, Replace, Remove };

static SoBRLEditPreview *
controller_edit_preview(const BObolViewController &controller,
    const char *previewId)
{
    auto *root = dynamic_cast<SoGroup *>(controller.getSceneRoot());
    if (!root)
	return nullptr;
    for (int i = 0; i < root->getNumChildren(); ++i) {
	SoNode *node = root->getChild(i);
	if (!node || !node->isOfType(SoBRLEditPreview::getClassTypeId()))
	    continue;
	auto *preview = static_cast<SoBRLEditPreview *>(node);
	if (preview->previewId.getValue() == previewId)
	    return preview;
    }
    return nullptr;
}

static bool
controller_edit_preview_matches(const SoBRLEditPreview *preview,
    const char *identity, const char *intentId, const char *intentRole,
    const SbVec3f *points, const int32_t *commands, int count,
    uint32_t sourceRevision, uint32_t inputsRevision)
{
    if (!preview || preview->previewId.getValue() != "controller-preview" ||
	preview->editIntentId.getValue() != intentId ||
	preview->editIntentRole.getValue() != intentRole ||
	preview->sourceRevision.getValue() != sourceRevision ||
	preview->inputsRevision.getValue() != inputsRevision ||
	preview->realizedSourceRevision.getValue() != sourceRevision ||
	preview->realizedInputsRevision.getValue() != inputsRevision ||
	preview->previewStatus.getValue() != SoBRLEditPreview::CURRENT ||
	preview->stale.getValue() || preview->needsRealization() ||
	preview->getNumChildren() != 1)
	return false;
    SoNode *node = preview->getChild(0);
    if (!node || !node->isOfType(SoBRLVListShape::getClassTypeId()))
	return false;
    const auto *shape = static_cast<const SoBRLVListShape *>(node);
    if (shape->sourcePath.getValue() != identity ||
	shape->sourceId.getValue() != sourceRevision ||
	shape->editIntentId.getValue() != intentId ||
	shape->editIntentRole.getValue() != intentRole ||
	shape->point.getNum() != count || shape->command.getNum() != count)
	return false;
    const SbVec3f *publishedPoints = shape->point.getValues(0);
    const int32_t *publishedCommands = shape->command.getValues(0);
    for (int i = 0; i < count; ++i)
	if (publishedPoints[i] != points[i] ||
	    publishedCommands[i] != commands[i])
	    return false;
    return true;
}

struct ControllerEditPreviewFixture {
    ControllerEditPreviewFixture(ControllerEditPreviewOperation requested,
	bool automaticLod) : operation(requested), automatic(automaticLod),
	peerOwner(retain_node(new SoSeparator))
    {
	root = dynamic_cast<SoGroup *>(controller.getSceneRoot());
	require(root != nullptr, "controller edit-preview scene root");
	root->addChild(peerOwner.get());
	if (operation != ControllerEditPreviewOperation::Insert) {
	    require(controller.replaceEditPreviewWithIntent(previewId,
		oldIdentity, oldIntentId, oldIntentRole, oldPoints,
		oldCommands, pointCount, oldSourceRevision,
		oldInputsRevision) == 1,
		"controller edit-preview initial publication");
	    initialPreview = controller_edit_preview(controller, previewId);
	    require(initialPreview && initialPreview->getNumChildren() == 1,
		"controller edit-preview initial node");
	    previewOwner = retain_node(initialPreview);
	    initialChild = initialPreview->getChild(0);
	    childOwner = retain_node(initialChild);
	    rootPath = make_test_path(root, 1);
	    childPath = make_test_path(initialPreview, 0);
	}
	if (automatic) {
	    struct bv_lod_policy policy;
	    bv_lod_policy_init(&policy);
	    policy.policy = BV_LOD_AUTO;
	    policy.mesh_enabled = policy.csg_enabled = 1;
	    controller.setViewLodPolicy(&policy);
	    controller.setLodAutoSubmit(TRUE);
	}
	(void)controller.finishPresentationRenderTiming(1,
	    rendererSampleNanoseconds, FALSE,
	    master_lighting_timing_context());
	controller.clearRenderRequest();
	controller.clearProgressiveWorkPending();
	initialSerial = controller.renderRequestSerialGet();
	controller.setFrameRequestCallback(wake, this);
	armed = true;
	require(isOld(), "controller edit-preview initial state");
    }

    ~ControllerEditPreviewFixture()
    {
	controller.clearFrameRequestCallback(this);
    }

    bool oldPreviewMatches() const
    {
	return controller_edit_preview_matches(initialPreview, oldIdentity,
	    oldIntentId, oldIntentRole, oldPoints, oldCommands, pointCount,
	    oldSourceRevision, oldInputsRevision);
    }

    bool nextPreviewMatches() const
    {
	return controller_edit_preview_matches(
	    controller_edit_preview(controller, previewId),
	    nextIdentity, nextIntentId, nextIntentRole, nextPoints,
	    nextCommands, pointCount, nextSourceRevision,
	    nextInputsRevision);
    }

    bool rootOld() const
    {
	if (root->getNumChildren() !=
		(operation == ControllerEditPreviewOperation::Insert ? 1 : 2) ||
	    root->getChild(0) != peerOwner.get())
	    return false;
	if (operation == ControllerEditPreviewOperation::Insert)
	    return controller_edit_preview(controller, previewId) == nullptr;
	return root->getChild(1) == initialPreview && oldPreviewMatches() &&
	    rootPath->getLength() == 2 && rootPath->getTail() == initialPreview &&
	    childPath->getLength() == 2 && childPath->getTail() == initialChild;
    }

    bool rootComplete() const
    {
	if (root->getChild(0) != peerOwner.get())
	    return false;
	if (operation == ControllerEditPreviewOperation::Remove)
	    return root->getNumChildren() == 1 &&
		controller_edit_preview(controller, previewId) == nullptr &&
		rootPath->getLength() == 1;
	SoBRLEditPreview *current = controller_edit_preview(controller, previewId);
	return root->getNumChildren() == 2 && root->getChild(1) == current &&
	    (operation != ControllerEditPreviewOperation::Replace ||
		current == initialPreview) && nextPreviewMatches() &&
	    (!rootPath || (rootPath->getLength() == 2 &&
		rootPath->getTail() == current)) &&
	    (!childPath || childPath->getLength() == 1);
    }

    bool isOld() const
    {
	return rootOld() &&
	    controller.getLastRenderTimeNanoseconds() ==
		rendererSampleNanoseconds && !controller.isRenderRequested() &&
	    !controller.hasProgressiveWorkPending() && frameCalls == 0 &&
	    controller.renderRequestSerialGet() == initialSerial;
    }

    bool hasPublishedState() const
    {
	const BObolHostWorkSnapshot work = controller.getHostWorkSnapshot();
	return rootComplete() &&
	    controller.getLastRenderTimeNanoseconds() ==
		rendererSampleNanoseconds &&
	    controller.isRenderRequested() &&
	    controller.getRenderReason() == "edit-preview" &&
	    !controller.hasProgressiveWorkPending() &&
	    work.capacitySampleRequested() &&
	    controller.renderRequestSerialGet() == initialSerial + 1;
    }

    bool isComplete() const
    {
	return hasPublishedState() && frameCalls == 1;
    }

    int publish()
    {
	return operation == ControllerEditPreviewOperation::Remove ?
	    controller.removeEditPreview(previewId) :
	    controller.replaceEditPreviewWithIntent(previewId, nextIdentity,
		nextIntentId, nextIntentRole, nextPoints, nextCommands,
		pointCount, nextSourceRevision, nextInputsRevision);
    }

    static void wake(void *data, const char *reason)
    {
	auto &self = *static_cast<ControllerEditPreviewFixture *>(data);
	if (!self.armed)
	    return;
	++self.frameCalls;
	self.incoherent = self.incoherent || !self.hasPublishedState() ||
	    std::string_view(reason ? reason : "") != "edit-preview";
	if (self.throwFrame)
	    throw std::bad_alloc();
    }

    static constexpr const char *previewId = "controller-preview";
    static constexpr const char *oldIdentity = "controller-preview-old";
    static constexpr const char *oldIntentId = "controller-intent-old";
    static constexpr const char *oldIntentRole = "preview-old";
    static constexpr const char *nextIdentity = "controller-preview-next";
    static constexpr const char *nextIntentId = "controller-intent-next";
    static constexpr const char *nextIntentRole = "preview-next";
    static constexpr int pointCount = 3;
    inline static const SbVec3f oldPoints[pointCount] = {
	SbVec3f(0.0f, 0.0f, 0.0f), SbVec3f(1.0f, 0.0f, 0.0f),
	SbVec3f(1.0f, 1.0f, 0.0f)};
    inline static const SbVec3f nextPoints[pointCount] = {
	SbVec3f(2.0f, 3.0f, 4.0f), SbVec3f(5.0f, 3.0f, 4.0f),
	SbVec3f(5.0f, 6.0f, 4.0f)};
    static constexpr int32_t oldCommands[pointCount] = {
	SoBRLVListShape::MOVE, SoBRLVListShape::DRAW, SoBRLVListShape::DRAW};
    static constexpr int32_t nextCommands[pointCount] = {
	SoBRLVListShape::MOVE, SoBRLVListShape::DRAW, SoBRLVListShape::POINT};
    static constexpr uint32_t oldSourceRevision = 7;
    static constexpr uint32_t oldInputsRevision = 11;
    static constexpr uint32_t nextSourceRevision = 13;
    static constexpr uint32_t nextInputsRevision = 17;
    static constexpr uint64_t rendererSampleNanoseconds = 6789012;

    const ControllerEditPreviewOperation operation;
    const bool automatic;
    BObolViewController controller;
    SoGroup *root = nullptr;
    TestNodeRef peerOwner;
    SoBRLEditPreview *initialPreview = nullptr;
    SoNode *initialChild = nullptr;
    TestNodeRef previewOwner{retain_node(nullptr)};
    TestNodeRef childOwner{retain_node(nullptr)};
    TestPathRef rootPath;
    TestPathRef childPath;
    uint64_t initialSerial = 0;
    size_t frameCalls = 0;
    bool armed = false;
    bool incoherent = false;
    bool throwFrame = false;
};

struct ControllerEditPreviewObserver {
    explicit ControllerEditPreviewObserver(
	ControllerEditPreviewFixture &target) : fixture(target), root(observe, this)
    {
	root.setPriority(0);
	root.attach(fixture.root);
	if (fixture.initialPreview &&
	    fixture.operation == ControllerEditPreviewOperation::Replace) {
	    field = std::make_unique<SoFieldSensor>(observe, this);
	    field->setPriority(0);
	    field->attach(&fixture.initialPreview->sourceRevision);
	}
	if (fixture.rootPath) {
	    path = std::make_unique<SoPathSensor>(observe, this);
	    path->setPriority(0);
	    path->attach(fixture.rootPath.get());
	}
    }

    static void observe(void *data, SoSensor *)
    {
	auto &self = *static_cast<ControllerEditPreviewObserver *>(data);
	++self.calls;
	self.incoherent = self.incoherent || !self.fixture.hasPublishedState();
	if (self.throwing)
	    throw std::bad_alloc();
    }

    ControllerEditPreviewFixture &fixture;
    SoNodeSensor root;
    std::unique_ptr<SoFieldSensor> field;
    std::unique_ptr<SoPathSensor> path;
    size_t calls = 0;
    bool incoherent = false;
    bool throwing = false;
};

struct ControllerEditPreviewReentry {
    BObolViewController *controller = nullptr;
    size_t frameCalls = 0;
    bool triggered = false;
    bool incoherent = false;

    bool matches() const
    {
	return controller_edit_preview_matches(
	    controller_edit_preview(*controller,
		ControllerEditPreviewFixture::previewId),
	    finalIdentity, finalIntentId, finalIntentRole, finalPoints,
	    finalCommands, ControllerEditPreviewFixture::pointCount,
	    finalSourceRevision, finalInputsRevision) &&
	    controller->getLastRenderTimeNanoseconds() ==
		ControllerEditPreviewFixture::rendererSampleNanoseconds &&
	    controller->isRenderRequested() &&
	    controller->getRenderReason() == "edit-preview";
    }

    static void wake(void *data, const char *reason)
    {
	auto &self = *static_cast<ControllerEditPreviewReentry *>(data);
	++self.frameCalls;
	if (!self.triggered) {
	    self.triggered = true;
	    const int changed = self.controller->replaceEditPreviewWithIntent(
		ControllerEditPreviewFixture::previewId, finalIdentity,
		finalIntentId, finalIntentRole, finalPoints, finalCommands,
		ControllerEditPreviewFixture::pointCount, finalSourceRevision,
		finalInputsRevision);
	    self.incoherent = self.incoherent || changed != 1;
	}
	self.incoherent = self.incoherent || !self.matches() ||
	    std::string_view(reason ? reason : "") != "edit-preview";
    }

    static constexpr const char *finalIdentity = "controller-preview-final";
    static constexpr const char *finalIntentId = "controller-intent-final";
    static constexpr const char *finalIntentRole = "preview-final";
    inline static const SbVec3f finalPoints[
	ControllerEditPreviewFixture::pointCount] = {
	SbVec3f(-1.0f, -2.0f, -3.0f), SbVec3f(0.0f, -2.0f, -3.0f),
	SbVec3f(0.0f, -1.0f, -3.0f)};
    static constexpr int32_t finalCommands[
	ControllerEditPreviewFixture::pointCount] = {
	SoBRLVListShape::MOVE, SoBRLVListShape::DRAW, SoBRLVListShape::DRAW};
    static constexpr uint32_t finalSourceRevision = 19;
    static constexpr uint32_t finalInputsRevision = 23;
};

static void
check_controller_edit_preview_input_publication()
{
    for (ControllerEditPreviewOperation operation : {
	ControllerEditPreviewOperation::Insert,
	ControllerEditPreviewOperation::Replace,
	ControllerEditPreviewOperation::Remove}) {
	for (bool automatic : {false, true}) {
	    ControllerEditPreviewFixture warmup(operation, automatic);
	    require(warmup.publish() == 1 && warmup.isComplete() &&
		!warmup.incoherent,
		"controller edit-preview warmup did not complete");
	}
    }

    size_t positions = 0, preserved = 0, committed = 0;
    for (ControllerEditPreviewOperation operation : {
	ControllerEditPreviewOperation::Insert,
	ControllerEditPreviewOperation::Replace,
	ControllerEditPreviewOperation::Remove}) {
	for (bool automatic : {false, true}) {
	    ControllerEditPreviewFixture measured(operation, automatic);
	    ControllerEditPreviewObserver measuredObserver(measured);
	    bool failed = false;
	    const size_t attempts = invoke_with_failure([&] {
		require(measured.publish() == 1,
		    "controller edit-preview measured return");
	    }, std::numeric_limits<size_t>::max(), failed);
	    require(!failed && measured.isComplete() &&
		measuredObserver.calls && !measuredObserver.incoherent &&
		!measured.incoherent,
		"controller edit-preview did not publish one complete state");
	    positions += attempts + 1;

	    for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
		ControllerEditPreviewFixture fixture(operation, automatic);
		ControllerEditPreviewObserver observer(fixture);
		failed = false;
		invoke_with_failure([&] {
		    require(fixture.publish() == 1,
			"controller edit-preview swept return");
		}, failAfter, failed);
		const bool old = fixture.isOld();
		require(old || fixture.isComplete(),
		    "controller edit-preview retained a partial state");
		require(!observer.incoherent && !fixture.incoherent,
		    "controller edit-preview observer saw a partial state");
		if (old) {
		    ++preserved;
		    require(failed && !observer.calls,
			"failed controller edit-preview changed old state");
		    require(fixture.publish() == 1,
			"controller edit-preview retry return");
		} else {
		    ++committed;
		}
		require(fixture.isComplete(),
		    "controller edit-preview retry did not complete");
	    }

	    ControllerEditPreviewFixture throwing(operation, automatic);
	    ControllerEditPreviewObserver observer(throwing);
	    observer.throwing = true;
	    failed = false;
	    try { (void)throwing.publish(); }
	    catch (const std::bad_alloc &) { failed = true; }
	    require(failed && throwing.isComplete() && observer.calls &&
		!observer.incoherent && !throwing.incoherent,
		"controller edit-preview observer failure changed publication");

	    ControllerEditPreviewFixture frameFailure(operation, automatic);
	    frameFailure.throwFrame = true;
	    failed = false;
	    try { (void)frameFailure.publish(); }
	    catch (const std::bad_alloc &) { failed = true; }
	    require(failed && frameFailure.isComplete() &&
		!frameFailure.incoherent,
		"controller edit-preview frame failure changed publication");
	}
    }

    BObolViewController invalid;
    invalid.clearRenderRequest();
    invalid.clearProgressiveWorkPending();
    bool failed = false;
    const size_t invalidAttempts = invoke_with_failure([&] {
	require(invalid.replaceEditPreviewWithIntent(
	    ControllerEditPreviewFixture::previewId, "invalid", "", "preview",
	    nullptr, nullptr, 0, 1, 1) == -1,
	    "invalid controller edit-preview return");
	require(invalid.removeEditPreview("missing-preview") == 0,
	    "missing controller edit-preview removal return");
    }, 0, failed);
    require(!failed && invalidAttempts == 0 &&
	!controller_edit_preview(invalid, ControllerEditPreviewFixture::previewId) &&
	!invalid.isRenderRequested() && !invalid.hasProgressiveWorkPending(),
	"invalid controller edit-preview allocated or changed state");

    ControllerEditPreviewFixture reentrant(
	ControllerEditPreviewOperation::Replace, false);
    reentrant.controller.clearFrameRequestCallback(&reentrant);
    reentrant.armed = false;
    ControllerEditPreviewReentry reentry{&reentrant.controller};
    reentrant.controller.setFrameRequestCallback(
	ControllerEditPreviewReentry::wake, &reentry);
    require(reentrant.publish() == 1,
	"controller edit-preview reentry outer return");
    require(reentry.triggered && reentry.matches() && reentry.frameCalls == 1 &&
	!reentry.incoherent,
	"controller edit-preview reentry did not retain the later successor");
    reentrant.controller.clearFrameRequestCallback(&reentry);

    std::printf("PASS controller-edit-preview-input-publication: %zu insert/replace/remove ordinary/automatic allocation positions, %zu preserved, %zu committed\n",
	positions, preserved, committed);
}

enum class ControllerLineLayerOperation { Insert, Replace, Remove };

static SoBRLLineLayerOverlay *
controller_line_layer(const BObolViewController &controller,
    const char *overlayId)
{
    auto *root = dynamic_cast<SoGroup *>(controller.getSceneRoot());
    if (!root)
	return nullptr;
    for (int i = 0; i < root->getNumChildren(); ++i) {
	SoNode *node = root->getChild(i);
	if (!node || !node->isOfType(SoBRLLineLayerOverlay::getClassTypeId()))
	    continue;
	auto *overlay = static_cast<SoBRLLineLayerOverlay *>(node);
	if (overlay->overlayId.getValue() == overlayId)
	    return overlay;
    }
    return nullptr;
}

static bool
controller_line_layer_matches(const SoBRLLineLayerOverlay *overlay,
    uint32_t sourceId, bool selectable, bool depthTest, int layerCount)
{
    if (!overlay || overlay->overlayId.getValue() != "controller-lines" ||
	overlay->sourceId.getValue() != sourceId ||
	overlay->visible.getValue() != TRUE ||
	overlay->selectable.getValue() != selectable ||
	overlay->depthTest.getValue() != depthTest ||
	overlay->getNumChildren() != layerCount + 1 ||
	overlay->getLayerShapeCount() != layerCount ||
	overlay->getPointCount() != static_cast<size_t>(layerCount * 2))
	return false;
    SoNode *depthNode = overlay->getChild(0);
    if (!depthNode || !depthNode->isOfType(SoDepthBuffer::getClassTypeId()))
	return false;
    const auto *depth = static_cast<const SoDepthBuffer *>(depthNode);
    if (depth->test.getValue() != depthTest ||
	depth->write.getValue() != depthTest ||
	depth->function.getValue() != SoDepthBuffer::LEQUAL)
	return false;
    for (int i = 0; i < layerCount; ++i) {
	const SoBRLVListShape *shape = overlay->getLayerShape(i);
	if (!shape || shape->sourceId.getValue() != sourceId ||
	    shape->selectable.getValue() != selectable ||
	    shape->sourcePath.getValue().getLength() == 0 ||
	    shape->point.getNum() != 2 || shape->command.getNum() != 2 ||
	    shape->command[0] != SoBRLVListShape::MOVE ||
	    shape->command[1] != SoBRLVListShape::DRAW)
	    return false;
    }
    return true;
}

struct ControllerLineLayerFixture {
    ControllerLineLayerFixture(ControllerLineLayerOperation requested,
	bool automaticLod) : operation(requested), automatic(automaticLod),
	oldBuilder(bg_line_layer_builder_create(), bg_line_layer_builder_free),
	nextBuilder(bg_line_layer_builder_create(), bg_line_layer_builder_free),
	peerOwner(retain_node(new SoSeparator))
    {
	require(bool(oldBuilder) && bool(nextBuilder),
	    "controller line-layer builder creation");
	add_test_line(oldBuilder.get(), 255, 0, 0, 0.0, 2.0);
	add_test_line(nextBuilder.get(), 0, 255, 0, 4.0, 6.0);
	add_test_line(nextBuilder.get(), 0, 0, 255, 8.0, 10.0);
	root = dynamic_cast<SoGroup *>(controller.getSceneRoot());
	require(root != nullptr, "controller line-layer scene root");
	root->addChild(peerOwner.get());
	if (operation != ControllerLineLayerOperation::Insert) {
	    require(controller.replaceLineLayerOverlay(overlayId,
		oldBuilder.get(), oldSourceId, oldSelectable, oldDepthTest) == 1,
		"controller line-layer initial publication");
	    initialOverlay = controller_line_layer(controller, overlayId);
	    require(initialOverlay && initialOverlay->getLayerShapeCount() == 1,
		"controller line-layer initial node");
	    overlayOwner = retain_node(initialOverlay);
	    initialShape = initialOverlay->getLayerShape(0);
	    shapeOwner = retain_node(initialShape);
	    rootPath = make_test_path(root, 1);
	    shapePath = make_test_path(initialOverlay, 1);
	}
	if (automatic) {
	    struct bv_lod_policy policy;
	    bv_lod_policy_init(&policy);
	    policy.policy = BV_LOD_AUTO;
	    policy.mesh_enabled = policy.csg_enabled = 1;
	    controller.setViewLodPolicy(&policy);
	    controller.setLodAutoSubmit(TRUE);
	}
	(void)controller.finishPresentationRenderTiming(1,
	    rendererSampleNanoseconds, FALSE,
	    master_lighting_timing_context());
	controller.clearRenderRequest();
	controller.clearProgressiveWorkPending();
	initialSerial = controller.renderRequestSerialGet();
	controller.setFrameRequestCallback(wake, this);
	armed = true;
	require(isOld(), "controller line-layer initial state");
    }

    ~ControllerLineLayerFixture()
    {
	controller.clearFrameRequestCallback(this);
    }

    int expectedReturn() const
    {
	return operation == ControllerLineLayerOperation::Remove ? 0 : 2;
    }

    int publish()
    {
	return controller.replaceLineLayerOverlay(overlayId,
	    operation == ControllerLineLayerOperation::Remove ? nullptr :
		nextBuilder.get(), nextSourceId, nextSelectable, nextDepthTest);
    }

    bool rootOld() const
    {
	if (root->getNumChildren() !=
		(operation == ControllerLineLayerOperation::Insert ? 1 : 2) ||
	    root->getChild(0) != peerOwner.get())
	    return false;
	if (operation == ControllerLineLayerOperation::Insert)
	    return controller_line_layer(controller, overlayId) == nullptr;
	return root->getChild(1) == initialOverlay &&
	    controller_line_layer_matches(initialOverlay, oldSourceId,
		oldSelectable, oldDepthTest, 1) &&
	    rootPath->getLength() == 2 && rootPath->getTail() == initialOverlay &&
	    shapePath->getLength() == 2 && shapePath->getTail() == initialShape;
    }

    bool rootComplete() const
    {
	if (root->getChild(0) != peerOwner.get())
	    return false;
	if (operation == ControllerLineLayerOperation::Remove)
	    return root->getNumChildren() == 1 &&
		controller_line_layer(controller, overlayId) == nullptr &&
		rootPath->getLength() == 1 && shapePath->getLength() == 2 &&
		controller_line_layer_matches(initialOverlay, oldSourceId,
		    oldSelectable, oldDepthTest, 1);
	SoBRLLineLayerOverlay *current =
	    controller_line_layer(controller, overlayId);
	return root->getNumChildren() == 2 && root->getChild(1) == current &&
	    current != initialOverlay &&
	    controller_line_layer_matches(current, nextSourceId,
		nextSelectable, nextDepthTest, 2) &&
	    (!rootPath || rootPath->getLength() == 1) &&
	    (!shapePath || (shapePath->getLength() == 2 &&
		shapePath->getTail() == initialShape));
    }

    bool isOld() const
    {
	return rootOld() &&
	    controller.getLastRenderTimeNanoseconds() ==
		rendererSampleNanoseconds && !controller.isRenderRequested() &&
	    !controller.hasProgressiveWorkPending() && frameCalls == 0 &&
	    controller.renderRequestSerialGet() == initialSerial;
    }

    bool hasPublishedState() const
    {
	const BObolHostWorkSnapshot work = controller.getHostWorkSnapshot();
	return rootComplete() &&
	    controller.getLastRenderTimeNanoseconds() ==
		rendererSampleNanoseconds && controller.isRenderRequested() &&
	    controller.getRenderReason() == "line-layer-overlay" &&
	    !controller.hasProgressiveWorkPending() &&
	    work.capacitySampleRequested() &&
	    controller.renderRequestSerialGet() == initialSerial + 1;
    }

    bool isComplete() const
    {
	return hasPublishedState() && frameCalls == 1;
    }

    static void wake(void *data, const char *reason)
    {
	auto &self = *static_cast<ControllerLineLayerFixture *>(data);
	if (!self.armed)
	    return;
	++self.frameCalls;
	self.incoherent = self.incoherent || !self.hasPublishedState() ||
	    std::string_view(reason ? reason : "") != "line-layer-overlay";
	if (self.throwFrame)
	    throw std::bad_alloc();
    }

    static constexpr const char *overlayId = "controller-lines";
    static constexpr uint32_t oldSourceId = 7;
    static constexpr uint32_t nextSourceId = 13;
    static constexpr bool oldSelectable = false;
    static constexpr bool nextSelectable = true;
    static constexpr bool oldDepthTest = true;
    static constexpr bool nextDepthTest = false;
    static constexpr uint64_t rendererSampleNanoseconds = 7890123;

    const ControllerLineLayerOperation operation;
    const bool automatic;
    TestLineLayerRef oldBuilder;
    TestLineLayerRef nextBuilder;
    BObolViewController controller;
    SoGroup *root = nullptr;
    TestNodeRef peerOwner;
    SoBRLLineLayerOverlay *initialOverlay = nullptr;
    SoNode *initialShape = nullptr;
    TestNodeRef overlayOwner{retain_node(nullptr)};
    TestNodeRef shapeOwner{retain_node(nullptr)};
    TestPathRef rootPath;
    TestPathRef shapePath;
    uint64_t initialSerial = 0;
    size_t frameCalls = 0;
    bool armed = false;
    bool incoherent = false;
    bool throwFrame = false;
};

