static void
check_controller_line_layer_input_publication()
{
    for (ControllerLineLayerOperation operation : {
	ControllerLineLayerOperation::Insert,
	ControllerLineLayerOperation::Replace,
	ControllerLineLayerOperation::Remove}) {
	for (bool automatic : {false, true}) {
	    ControllerLineLayerFixture warmup(operation, automatic);
	    require(warmup.publish() == warmup.expectedReturn() &&
		warmup.isComplete() && !warmup.incoherent,
		"controller line-layer warmup did not complete");
	}
    }

    size_t positions = 0, preserved = 0, committed = 0;
    for (ControllerLineLayerOperation operation : {
	ControllerLineLayerOperation::Insert,
	ControllerLineLayerOperation::Replace,
	ControllerLineLayerOperation::Remove}) {
	for (bool automatic : {false, true}) {
	    ControllerLineLayerFixture measured(operation, automatic);
	    ControllerLineLayerObserver measuredObserver(measured);
	    bool failed = false;
	    const size_t attempts = invoke_with_failure([&] {
		require(measured.publish() == measured.expectedReturn(),
		    "controller line-layer measured return");
	    }, std::numeric_limits<size_t>::max(), failed);
	    require(!failed && measured.isComplete() &&
		measuredObserver.calls && !measuredObserver.incoherent &&
		!measured.incoherent,
		"controller line-layer did not publish one complete state");
	    positions += attempts + 1;

	    for (size_t failAfter = 0; failAfter <= attempts; ++failAfter) {
		ControllerLineLayerFixture fixture(operation, automatic);
		ControllerLineLayerObserver observer(fixture);
		failed = false;
		invoke_with_failure([&] {
		    require(fixture.publish() == fixture.expectedReturn(),
			"controller line-layer swept return");
		}, failAfter, failed);
		const bool old = fixture.isOld();
		require(old || fixture.isComplete(),
		    "controller line-layer retained a partial state");
		require(!observer.incoherent && !fixture.incoherent,
		    "controller line-layer observer saw a partial state");
		if (old) {
		    ++preserved;
		    require(failed && !observer.calls,
			"failed controller line-layer changed old state");
		    require(fixture.publish() == fixture.expectedReturn(),
			"controller line-layer retry return");
		} else {
		    ++committed;
		}
		require(fixture.isComplete(),
		    "controller line-layer retry did not complete");
	    }

	    ControllerLineLayerFixture throwing(operation, automatic);
	    ControllerLineLayerObserver observer(throwing);
	    observer.throwing = true;
	    failed = false;
	    try { (void)throwing.publish(); }
	    catch (const std::bad_alloc &) { failed = true; }
	    require(failed && throwing.isComplete() && observer.calls &&
		!observer.incoherent && !throwing.incoherent,
		"controller line-layer observer failure changed publication");

	    ControllerLineLayerFixture frameFailure(operation, automatic);
	    frameFailure.throwFrame = true;
	    failed = false;
	    try { (void)frameFailure.publish(); }
	    catch (const std::bad_alloc &) { failed = true; }
	    require(failed && frameFailure.isComplete() &&
		!frameFailure.incoherent,
		"controller line-layer frame failure changed publication");
	}
    }

    BObolViewController invalid;
    TestLineLayerRef builder(bg_line_layer_builder_create(),
	bg_line_layer_builder_free);
    require(bool(builder), "invalid controller line-layer builder");
    add_test_line(builder.get(), 255, 255, 255, 0.0, 1.0);
    invalid.clearRenderRequest();
    invalid.clearProgressiveWorkPending();
    bool failed = false;
    const size_t invalidAttempts = invoke_with_failure([&] {
	require(invalid.replaceLineLayerOverlay("", builder.get(), 1,
		TRUE, TRUE) == -1,
	    "invalid controller line-layer return");
	require(invalid.replaceLineLayerOverlay("missing-lines", nullptr, 0,
		TRUE, TRUE) == 0,
	    "missing controller line-layer removal return");
    }, 0, failed);
    require(!failed && invalidAttempts == 0 &&
	!controller_line_layer(invalid, "missing-lines") &&
	!invalid.isRenderRequested() && !invalid.hasProgressiveWorkPending(),
	"invalid controller line-layer allocated or changed state");

    ControllerLineLayerFixture reentrant(
	ControllerLineLayerOperation::Replace, false);
    reentrant.controller.clearFrameRequestCallback(&reentrant);
    reentrant.armed = false;
    ControllerLineLayerReentry reentry;
    reentry.controller = &reentrant.controller;
    reentrant.controller.setFrameRequestCallback(
	ControllerLineLayerReentry::wake, &reentry);
    require(reentrant.publish() == reentrant.expectedReturn(),
	"controller line-layer reentry outer return");
    require(reentry.triggered && reentry.matches() && reentry.frameCalls == 1 &&
	!reentry.incoherent,
	"controller line-layer reentry did not retain the later successor");
    reentrant.controller.clearFrameRequestCallback(&reentry);

    std::printf("PASS controller-line-layer-input-publication: %zu insert/replace/remove ordinary/automatic allocation positions, %zu preserved, %zu committed\n",
	positions, preserved, committed);
}

enum class ControllerHudLabelOperation { Insert, Replace, Remove };

static SoBRLHUDLabelOverlay *
controller_hud_label(const BObolViewController &controller,
    const char *labelId)
{
    auto *root = dynamic_cast<SoGroup *>(controller.getSceneRoot());
    if (!root)
	return nullptr;
    for (int i = 0; i < root->getNumChildren(); ++i) {
	SoNode *node = root->getChild(i);
	if (!node || !node->isOfType(SoBRLHUDLabelOverlay::getClassTypeId()))
	    continue;
	auto *label = static_cast<SoBRLHUDLabelOverlay *>(node);
	if (label->labelId.getValue() == labelId)
	    return label;
    }
    return nullptr;
}

static bool
controller_hud_label_matches(const SoBRLHUDLabelOverlay *overlay,
    const char *text, const SbVec2f &position, const SbColor &color,
    float fontSize, uint32_t sourceId)
{
    if (!overlay || overlay->labelId.getValue() != "controller-label" ||
	overlay->sourceId.getValue() != sourceId ||
	overlay->text.getValue() != text ||
	overlay->position.getValue() != position ||
	overlay->color.getValue() != color ||
	std::fabs(overlay->fontSize.getValue() - fontSize) >
	    std::numeric_limits<float>::epsilon() ||
	overlay->visible.getValue() != TRUE || overlay->getNumChildren() != 1)
	return false;
    SoHUDKit *kit = overlay->getHUDKit();
    SoHUDLabel *label = overlay->getHUDLabel();
    return kit && overlay->getChild(0) == kit && label &&
	label->string.getNum() == 1 && label->string[0] == text &&
	label->position.getValue() == position &&
	label->color.getValue() == color &&
	std::fabs(label->fontSize.getValue() - fontSize) <=
	    std::numeric_limits<float>::epsilon();
}

